(window.GIM_TS=window.GIM_TS||{})["Gittin.7"]={"from":168,"a":[["הרי זה \u0003לאפוקי\u0004 \u0005[להוציא]\u0006 \u0003מדבעא מיניה\u0004 \u0005[ממה ששאל אותו]\u0006 \u0003רבא מרב נחמן,\u0004 במקרה ש\u0003אמר \"היום אי\u0004 (אין) \u0003את אשתי ולמחר את אשתי\"\u0004 האם יש לחשוש לתנאי זה בגט. ואף שאותה שאלה נפתרה, שכיון שגירשה — הריהי גרושה לעולם, מכל מקום כדי להוציא מן הספק קבע רבא שיאמר בנוסח זה שהוא פוטר, מגרש, אותה לעולם.","שנינו במשנה: \u0003גופו של גט שחרור: \"הרי את בת חורין, הרי את לעצמך\".\u0004 מסופר: \u0003אתקין\u0004 \u0005[התקין]\u0006 \u0003רב יהודה בשטר זביני דעבדי\u0004 \u0005[מכירה של עבדים]\u0006 לשון זו: \u0003\"עבדא דנן\u0004 \u0005[עבד זה]\u0006 \u0003מוצדק\u0004 (ראוי) \u0003לעבדו\u0004 \u0005[לעבדות],\u0006 \u0003ופטיר ועטיר מן חרורי ומן עלולי ומן ערורי מלכא ומלכתא\u0004 \u0005[ופטור ומוסר משחרורים ומעלילות ומערעורים של המלך והמלכה]\u0006 \u0003ורשום דאיניש לא אית עלוהי\u0004 \u0005[וסימן\u0006 מרות \u0005של אדם\u0006 אחר \u0005אין עליו],\u0006 \u0003ומנוקה מכל מום ומן שחין דנפיק\u0004 \u0005[שיצא בו]\u0006 \u0003עד טצהר חדת ועתיק\u0004 \u0005[שנתיים,\u0006 בין \u0005חדש ו\u0006בין \u0005ישן].\u0006","ושואלים בדרך אגב: \u0003מאי אסותיה\u0004 \u0005[מה רפואתו]\u0006 של השחין? \u0003אמר אביי: גינברא ומרתכא וכבריתא\u0004 \u0005[זנגביל, וסיגי כסף וגופרית],\u0006 \u0003וחלא דחמרא\u0004 \u0005[וחומץ יין]\u0006 \u0003ומשחא דזיתא\u0004 \u0005[ושמן זית]\u0006 \u0003ונטפיק חיורא\u0004 \u0005[לבן],\u0006 \u0003ושייפי ליה בגדפא דאווזא\u0004 \u0005[ומורחים אותו בנוצה של אווז].\u0006","\u0003שלשה גיטין פסולין\u0004 הם לכתחילה, \u0003ו\u0004מכל מקום \u0003אם נשאת\u0004 על סמך גט שכזה \u0003הוולד כשר.\u0004","ואלו הם: אם \u0003כתב\u0004 את הגט כולו \u0003בכתב ידו ואין עליו עדים,\u0004 או גט ש\u0003יש עליו עדים ואין בו זמן\u0004 (תאריך), או \u0003יש בו זמן ואין בו אלא עד אחד, הרי אלו שלשה גיטין פסולין, ואם נשאת\u0004 — \u0003הולד כשר.\u0004","\u0003ר' אליעזר אומר: אף על פי שאין עליו עדים אלא שנתנו לה בפני עדים,\u0004 הרי זה \u0003כשר\u0004 לגמרי, \u0003וגובה\u0004 האשה מכח גט זה גם \u0003מנכסים משועבדים,\u0004 וטעמו — לפי \u0003שאין העדים חותמים על הגט אלא מפני תיקון העולם,\u0004 שאם יהא עליו עירעור אפשר יהא לקיימו על פי חתימתם, אבל לעצם כשרות הגט אין חתימת העדים משנה, והכל תלוי בעדות המסירה.","על האמור במשנה ששלושה גיטין פסולים הם, שואלים: \u0003ותו ליכא\u0004 \u0005[ועוד אין]\u0006 גיטין פסולים אחרים? \u0003והא איכא\u0004 \u0005[והרי יש]\u0006 \u0003גט ישן\u0004 שנתייחד עם אשתו לאחר שכתבו! ומשיבים, יש הבדל בין הדברים: \u0003התם\u0004 \u0005[שם]\u0006 בגט ישן \u0003לא תצא\u0004 מן הבעל השני שנישאה לו מכוח גט זה, \u0003הכא\u0004 \u0005[כאן]\u0006 \u0003תצא.\u0004","ושואלים: \u0003הניחא למאן דאמר הכא\u0004 \u0005[זה נוח ל\u0006דעת \u0005מי שאומר\u0006 ומפרש \u0005כאן]\u0006 שלמרות שהוולד כשר, בכל זאת \u0003תצא\u0004 מבעלה, \u0003אלא למאן דאמר הכא\u0004 \u0005[ל\u0006דעת \u0005מי שאומר כאן]\u0006 \u0003לא תצא, מאי איכא למימר\u0004 \u0005[מה יש לומר]?\u0006 שהרי דין גט ישן כדין הגיטין המנויים במשנה, ומדוע לא שנה כאן גם גט ישן?","ומשיבים: שונה דין גט ישן שכן \u0003התם\u0004 \u0005[שם]\u0006 בגט ישן \u0003תינשא לכתחלה\u0004 לאחר, ואילו \u0003הכא\u0004 \u0005[כאן]\u0006 רק \u0003דיעבד,\u0004 אם נישאת לא תצא.","ומקשים: \u0003והא איכא\u0004 \u0005[והרי יש]\u0006 \u0003גט קרח\u0004 (גט מקושר, שהיו בו קשרים יותר ממספר העדים שחתומים עליו), שגם הוא פסול! ומשיבים: \u0003התם\u0004 \u0005[שם]\u0006 אם נישאה על ידו \u0003הולד ממזר, הכא\u0004 \u0005[כאן]\u0006 \u0003הולד כשר.\u0004","ומקשים: \u0003הניחא\u0004 \u0005[זה נוח]\u0006 \u0003ל\u0004דעת \u0003ר' מאיר,\u0004 ש\u0003אמר: כל המשנה ממטבע שטבעו\u0004 (ממתכונת שתיקנו) \u0003חכמים בגיטין הולד ממזר,\u0004 ולכן גט קרח פסול לחלוטין, ואם נישאת בו הוולד ממזר, \u0003אלא לרבנן\u0004 \u0005[ל\u0006שיטת \u0005חכמים]\u0006 שאין הוולד ממזר, \u0003מאי איכא למימר\u0004 \u0005[מה יש לומר]?\u0006 מדוע לא נמנה גט קרח בין הגיטין המנויים במשנה?","ומשיבים, לשיטתם יש לחלק בדרך אחרת: \u0003התם\u0004 \u0005[שם]\u0006 אף שהוולד אינו ממזר מכל מקום \u0003תצא\u0004 מבעלה, \u0003הכא\u0004 \u0005[כאן]\u0006 \u0003לא תצא.\u0004","ומקשים: \u0003הניחא למאן דאמר הכא\u0004 \u0005[זה נוח ל\u0006דעת \u0005מי שאומר כאן]\u0006 \u0003לא תצא\u0004 מבעלה, \u0003אלא למאן דאמר הכא\u0004 \u0005[ל\u0006דעת \u0005מי שאומר כאן]\u0006 \u0003תצא, מאי איכא למימר\u0004 \u0005[מה יש לומר]?\u0006 ומשיבים: צריך לומר ש\u0003ב\u0004גט \u0003מקושר לא קא מיירי\u0004 \u0005[אינו עוסק]\u0006 אלא בגט פשוט, ובגט פשוט יש רק שלושה גיטין פסולים מסוג זה, שיוצאת מבעלה השני, אף שהוולד ממנו כשר.","ומקשים: \u0003והא איכא\u0004 \u0005[והרי יש]\u0006 גט שפסול משום \u0003שלום מלכות,\u0004 שכתוב בו תאריך לפי זמן שלטונה של מלכות אחרת, ומדוע לא נמנה במשנתנו! ומשיבים: \u0003התם\u0004 \u0005[שם]\u0006 אין זה דומה, שכן \u0003תצא\u0004 מבעלה, \u0003הכא\u0004 \u0005[כאן]\u0006 \u0003לא תצא.\u0004","ומקשים: \u0003הניחא למאן דאמר הכא\u0004 \u0005[זה נוח ל\u0006דעת \u0005מי שאומר כאן]\u0006 \u0003לא תצא, אלא למאן דאמר\u0004 \u0005[ל\u0006דעת \u0005מי שאומר]\u0006 \u0003תצא, מאי איכא למימר\u0004 \u0005[מה יש לומר]?\u0006 ומשיבים: \u0003התם\u0004 \u0005[שם]\u0006 \u0003הולד ממזר, הכא\u0004 \u0005[כאן]\u0006 \u0003הולד כשר.\u0004","ומקשים עוד: \u0003הניחא\u0004 \u0005[זה נוח]\u0006 \u0003ל\u0004שיטת \u0003ר' מאיר, אלא לרבנן\u0004 \u0005[ל\u0006שיטת \u0005חכמים]\u0006 שאין הוולד ממזר \u0003מאי איכא למימר\u0004 \u0005[מה אפשר לומר]?\u0006 ומשיבים: חכם זה, הסבור שבגיטין פסולים שבמשנה זו תצא אשה מבעלה, \u0003מוקים לה\u0004 \u0005[מעמיד אותה,\u0006 את המשנה\u0005]\u0006 \u0003כ\u0004דברי \u0003ר' מאיר, ו\u0004לפי שיטתו יש הבדל, \u0003התם\u0004 \u0005[שם]\u0006 \u0003הולד ממזר, הכא\u0004 \u0005[כאן]\u0006 \u0003הולד כשר.\u0004","ועוד שואלים: במשנה מודגש שתי פעמים שיש שלושה גיטין פסולים, \u0003מנינא דרישא למעוטי מאי, ומנינא דסיפא למעוטי מאי\u0004 \u0005[המנין שבראש\u0006 המשנה \u0005למעט\u0006 את \u0005מה בא, והמנין שבסוף\u0006 המשנה \u0005למעט\u0006 את \u0005מה]?\u0006","ומשיבים \u0003מנינא דרישא\u0004 — \u0003למעוטי הני דאמרן\u0004 \u0005[המנין שבראש\u0006 בא \u0005למעט\u0006 את \u0005אלה שאמרנו]\u0006 קודם, כל המקרים שאין נמנים ברשימה זו שבמשנתנו, משום שהם חמורים יותר.","\u0003מנינא דסיפא\u0004 — \u0003למעוטי הא דתניא\u0004 \u0005[המנין שבסוף למעט\u0006 את \u0005זו ששנינו\u0006 בברייתא\u0005]:\u0006 \u0003המביא גט ממדינת הים, נתנו לה ולא אמר לה \"בפני נכתב ובפני נחתם\"\u0004 — \u0003יוציא והולד ממזר,\u0004 אלו \u0003דברי ר' מאיר,\u0004","\u0003וחכמים אומרים: אין הולד ממזר,\u0004 אלא \u0003כיצד יעשה? יטלנו הימנה, ויחזור ויתננו לה בפני שנים, ויאמר \"בפני נכתב ובפני נחתם\",\u0004 וכיון שיש שם תקנה לדבר — אין למנותו בין הגיטין הפסולים שבמשנתנו.","שנינו במשנה: \u0003כתב בכתב ידו ואין עליו עדים\u0004 — הרי זה פסול, ואולם הוולד מן הבעל השני כשר. \u0003אמר רב: \"כתב ידו\" שנינו.\u0004","ותוהים: \u0003אהייא\u0004 \u0005[על איזו]\u0006 פיסקה מן המשנה אמר רב את דבריו? \u0003אילימא ארישא\u0004 \u0005[אם תאמר על ראשה]\u0006 — \u0003פשיטא\u0004 \u0005[פשוט,\u0006 מובן מאליו\u0005]\u0006 שכן הוא, שהרי \u0003\"כתב ידו\" קתני\u0004 \u0005[שנה]!\u0006","\u0003ואלא\u0004 תפרש שאמר דברים אלה על \u0003אמצעיתא\u0004 \u0005[על\u0006 הקטע \u0005האמצעי במשנה],\u0006 בגט שאין בו תאריך — אולם למה צריך שיהא בכתב ידו? \u0003הרי יש עליו עדים! אלא\u0004 יש לפרש \u0003אסיפא\u0004 \u0005[על סוף]\u0006 המשנה: בגט ש\u0003יש בו זמן ואין בו אלא עד אחד,\u0004"],["\u0003ודוקא כתב ידו\u0004 שלו \u0003ו\u0004חתימת \u0003עד,\u0004 אם נישאת — הוולד מן השני כשר, והחידוש שבכך הוא ללמד: \u0003אבל כתב סופר ו\u0004חתימת \u0003עד\u0004 — \u0003לא,\u0004 והגט בטל לגמרי, ואם נישאת הוולד מן השני ממזר.","\u0003ושמואל אמר: אפילו כתב סופר ועד\u0004 הוולד מן השני כשר, \u0003שהרי שנינו\u0004 במשנה להלן: \u0003כתב סופר ועד\u0004 — \u0003כשר.\u0004","\u0003ורב\u0004 משיב על ראיה זו: \u0003מי דמי\u0004 \u0005[האם דומה]?\u0006 \u0003התם\u0004 \u0005[שם]\u0006 במשנה המכשירה נאמר אף ש\u0003תינשא לכתחילה,\u0004 ולפיכך יש לפרש במשנה זו שמדובר שהסופר אף חתם כעד שני, ואילו \u0003הכא\u0004 \u0005[כאן]\u0006 במשנה שלנו מדובר ב\u0003דיעבד,\u0004 שאף שהגט פסול ואסורה להינשא — הוולד כשר, ואין להשוות את שני המקרים.","\u0003ושמואל\u0004 הסבור שאף שם מדובר שהסופר כתב ולא חתם מסביר את הסתירה כך: \u0003לא קשיא\u0004 \u0005[אינו קשה]:\u0006 \u0003הא\u0004 \u0005[זה]\u0006 שכשר לכתחילה מדובר \u0003בספרא\u0004 \u0005[בסופר]\u0006 שהוא \u0003מובהק\u0004 שמובטחים אנו בו שכתב כראוי, ורק כפי שאמר לו הבעל, ולכן אפשר לסמוך על כתבו אף לכתחילה, \u0003והא\u0004 \u0005[וזה]\u0006 במשנתנו מדובר \u0003בספרא\u0004 \u0005[בסופר]\u0006 ש\u0003לא מובהק\u0004 שיש לחשוש שמא לא נגמר הגט כראוי, כיון שלא נחתם בשני עדים.","\u0003וכן אמר ר' יוחנן\u0004 כרב: \u0003כתב ידו שנינו. אמר ליה\u0004 \u0005[לו]\u0006 \u0003ר' אלעזר:\u0004 שחשב כי ר' יוחנן מפרש את הפיסקה הראשונה במשנתנו, \u0003הרי יש עליו עדים!\u0004 ולמה נחוץ בזה כתב ידו? \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003אסיפא\u0004 \u0005[על סופה]\u0006 של המשנה אמרתי, לגבי גט שיש בו עד אחד.","ולעצם ההלכה במשנה באותם שלושה גיטין פסולים, \u0003זימנין\u0004 \u0005[לפעמים]\u0006 \u0003אמר רב תצא\u0004 מבעלה השני שנישאה לו על סמך גט כזה, \u0003זימנין\u0004 \u0005[לפעמים]\u0006 \u0003אמר רב: לא תצא.\u0004","ומסבירים: \u0003הא כיצד,\u0004 איך ליישב את הסתירה בדברי רב? — אם כבר \u0003יש לה בנים\u0004 מבעלה השני — \u0003לא תצא\u0004 מבעלה, שהרי אם יכריחוה לצאת יצא בכך לעז על בניה שהם ממזרים, ואם \u0003אין לה בנים\u0004 — \u0003תצא.\u0004","\u0003מתיב\u0004 \u0005[מקשה]\u0006 \u0003מר זוטרא בר טוביה\u0004 על כך ממה ששנינו במשנה במסכת יבמות, לגבי חמש עשרה נשים שהן בגדר ערווה ליבם, שלא זו בלבד שהן עצמן פטורות מן היבום, אלא אף פוטרות צרותיהן (אשה נוספת שהיתה נשואה לאח שמת, והיא כשלעצמה מותרת ליבם) מן החליצה ומן היבום, אבל אם נתגרשו נשים אלה לפני מות האח — הצרה אינה נפטרת מן היבום. ואמרו במשנה: \u0003וכולן,\u0004 כל הנשים הפוטרות מן היבום, \u0003שהיו בהן ספק קידושין או ספק גירושין\u0004 — \u0003הרי אלו,\u0004 הצרות שלהן, \u0003חולצות ולא מתיבמות.\u0004","ומפרטת המשנה: \u0003כיצד ספק קידושין?\u0004 — \u0003זרק לה\u0004 שטר או כסף \u0003קידושין\u0004 לאשה, \u0003ספק\u0004 נפלו \u0003קרוב לה\u0004 וזכתה בהם, והרי היא מקודשת, \u0003ספק קרוב לו\u0004 ולא זכתה בהם, ואין היא מקודשת — \u0003זהו ספק קידושין.\u0004","מהו \u0003ספק גירושין?\u0004 — אותם גיטין הפסולים במשנתנו: אם \u0003כתב בכתב ידו ואין עליו עדים,\u0004 או \u0003יש עליו עדים ואין בו זמן, יש בו זמן ואין בו אלא עד אחד\u0004 — \u0003הרי זה ספק גירושין.\u0004","\u0003ואי אמרת\u0004 \u0005[ואם אומר אתה]\u0006 \u0003לא תצא,\u0004 הרי אם גירשה בעלה (האח שמת) בגט כזה שיש בו ספק והשאיר גם אשה אחרת, הרי \u0003צרתה\u0004 זו \u0003אתיא ליבומי\u0004 \u0005[תבוא להתייבם]\u0006 שיאמרו שזו כבר נתגרשה גירושין גמורים, ואם כן צרתה יכולה להתייבם. והרי גירושין אלה היה בהם ספק, והצרה היא איפוא \"ספק צרת ערווה\" ואסורה ליבם!","ומשיבים: \u0003תתיבם, ואין בכך כלום,\u0004 הרי הבעיה בגט זה היא רק \u0003חששא דרבנן\u0004 \u0005[חשש מדברי חכמים]\u0006 \u0003היא,\u0004 ומן התורה גט גמור הוא, ובאמת ראויה צרתה להתייבם. עד כאן הדיון בדברי רב ולדעתו אם נישאה האשה על סמך גיטין שבמשנתנו אך לא נולדו לה ילדים מנישואין אלה — תצא מבעלה.","ואילו \u0003לוי אמר: לעולם,\u0004 בין שהיו לה בנים או לא — \u0003לא תצא.\u0004 \u0003וכן אמר ר' יוחנן: לעולם לא תצא.\u0004","\u0003וכן אמר להו\u0004 \u0005[להם]\u0006 \u0003ר' יוחנן לבני ר' חלפתא\u0004 ש\u0003מן הונא, הכי אמר אבוכון\u0004 \u0005[כך אמר אביכם]\u0006 שני דברים, שקיבלתי ממנו: \u0003לעולם לא תצא.\u0004 \u0003ו\u0004עוד אמר, ש\u0003קרצית שבעמיר אינה פוסלת במי חטאת\u0004 (מים עם אפר פרה אדומה), שאם שתתה ממים אלה — אינה פוסלת אותם, ומותר להזות מהם על מנת לטהר מטומאת מת.","ושואלים: \u0003מאי\u0004 \u0005[מה]\u0006 היא \u0003קרצית\u0004 זו? \u0003אמר אביי: דידבתא דביני כיפי\u0004 \u0005[\u0006מין \u0005זבוב ה\u0006מצוי \u0005בין האלומות].\u0006","\u0003מתיב\u0004 \u0005[מקשה]\u0006 \u0003רב דניאל בר רב קטינא,\u0004 שנינו במסכת פרה: \u0003כל העופות פוסלין במי חטאת\u0004 כאשר הם שותים מהם, מפני שמקצת המים חוזרים ונשפכים מפיהם חזרה לכלי, ומים שהיו בפיהם — נפסלו, \u0003חוץ מן היונה, מפני שמוצצת\u0004 ואינה מחזירה. \u0003ואם איתא\u0004 \u0005[יש]\u0006 מקום להלכה זו בקרצית, אם כן \u0003ניתני\u0004 \u0005[שישנה]\u0006 באותה משנה: \u0003חוץ מיונה וקרצית!\u0004","ומשיבים \u0003לא פסיקא ליה\u0004 \u0005[אין\u0006 הדבר \u0005פסוק,\u0006 מוחלט \u0005לו]\u0006 לפרש אותו במשנה, כי לא כל קרצית אינה פוסלת, שקרצית \u0003גדולה לא פסלה\u0004 \u0005[פוסלת],\u0006 \u0003ו\u0004אולם \u0003קטנה\u0004 \u0003פסלה\u0004 \u0005[פוסלת].\u0006 ושואלים: \u0003ועד כמה\u0004 שיעורה להיחשב קטנה? \u0003אמר ר' ירמיה, ואיתימא\u0004 \u0005[ויש אומרים]\u0006 שאמר זאת \u0003ר' אמי: עד כזית.\u0004","שנינו במשנה ש\u0003ר' אלעזר אומר: אף על פי\u0004 שאין בגט עדים, אם מסרו לה בעדים — הרי הוא כשר. \u0003אמר רב יהודה אמר רב: הלכה כ\u0004שיטת \u0003ר' אלעזר בגיטין. כי אמריתה קמיה\u0004 \u0005[כאשר אמרתי אותה,\u0006 את \u0003הלכה זו\u0004 \u0005לפני]\u0006 \u0003שמואל,\u0004 \u0003אמר: אף בשטרות\u0004 הלכה כר' אלעזר.","ושואלים: \u0003ו\u0004כי \u0003רב סבר\u0004 כי \u0003בשטרות לא\u0004 הלכה כר' אלעזר? \u0003הא קתני\u0004 \u0005[הרי שנה]\u0006 במשנה: \u0003וגובה מנכסים משועבדים,\u0004 משמע שאם מקבלים את העקרון של ר' אלעזר הרי שטר כזה נחשב כשטר גמור לכל דבר!","ומשיבים: \u0003ר' אלעזר תרתי\u0004 \u0005[שני\u0006 דברים\u0005]\u0006 \u0003אמר,\u0004 גם בענין גיטין וגם בענין שטרות, \u0003ורב סבר כוותיה בחדא ופליג עליה בחדא\u0004 \u0005[סבור כמותו ב\u0006דבר \u0005אחד,\u0006 בגיטין, \u0005וחולק עליו באחד,\u0006 בשטרות\u0005].\u0006","\u0003וכן אמר ר' יעקב בר אידי אמר ר' יהושע בן לוי: הלכה כ\u0004שיטת \u0003ר' אלעזר בגיטין. ור' ינאי אמר: אפילו ריח הגט אין בו,\u0004 בגט כזה שאין חתומים בו עדים.","ותוהים: \u0003ור' ינאי לית ליה\u0004 \u0005[אין לו,\u0006 אינו מקבל\u0005]\u0006 כלל את שיטת \u0003ר' אלעזר,\u0004 ובניגוד לשאר האמוראים? ומתקנים: \u0003הכי קאמר\u0004 \u0005[כך אמר],\u0006 כך צריך להבין את דבריו: \u0003ל\u0004דעת \u0003רבנן\u0004 \u0005[חכמים]\u0006 החולקים על ר' אלעזר \u0003אפילו ריח הגט אין בו.\u0004","\u0003וכן אמר ר' יוסי בר' חנינא אמר ריש לקיש: הלכה כ\u0004שיטת \u0003ר' אלעזר בגיטין, ור' יוחנן אמר: אפילו ריח הגט אין בו.\u0004","ושואלים: \u0003לימא\u0004 \u0005[האם נאמר]\u0006 ש\u0003ר' יוחנן לית ליה\u0004 \u0005[אין לו,\u0006 אינו מקבל\u0005]\u0006 כלל את שיטתו של \u0003ר' אלעזר?\u0004 ומשיבים: \u0003הכי קאמר\u0004 \u0005[כך אמר]:\u0006 \u0003ל\u0004דעת \u0003רבנן\u0004 \u0005[חכמים]\u0006 החולקים על ר' אלעזר, \u0003אפילו ריח הגט אין בו.\u0004","\u0003שלח ליה\u0004 \u0005[לו]\u0006 \u0003ר' אבא בר זבדא למרי בר מר\u0004 בקשה זו: \u0003בעי מיניה\u0004 \u0005[שאל אותו]\u0006 \u0003מרב הונא:\u0004 האם \u0003הלכה כ\u0004שיטת \u0003ר' אלעזר בגיטין, או אין הלכה\u0004 כמותו?","\u0003אדהכי\u0004 \u0005[בינתיים]\u0006 לפני שהגיעה אליו השאלה \u0003נח נפשיה\u0004 \u0005[נפטר]\u0006 \u0003רב הונא,\u0004 \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבה בריה\u0004 \u0005[בנו]\u0006 של רב הונא למרי בר מר, \u0003הכי\u0004 \u0005[כך]\u0006 \u0003אמר אבא משמיה\u0004 \u0005[משמו]\u0006 של \u0003רבא: הלכה כ\u0004שיטת \u0003ר' אלעזר בגיטין ו\u0004כן \u0003רבותינו הבקיאין בדבר הלכה, משום רבינו\u0004 (רב) \u0003אמרו: הלכה כ\u0004שיטת \u0003ר' אלעזר בגיטין,\u0004 ולמי הוא רומז בכינוי \"רבותינו\" — למה ש\u0003אמר רב חמא בר גוריא אמר רב: הלכה כ\u0004שיטת \u0003ר' אלעזר בגיטין.\u0004","\u0003איכא דאמרי\u0004 \u0005[יש שאומרים]\u0006 שאמר זאת בלשון זו: \u0003וחברינו הבקיאין בדבר הלכה, ותלמידי רבינו, משום רבינו אמרו: הלכה כ\u0004שיטת \u0003ר' אלעזר בגיטין,\u0004 כי המסורת היתה כך, ש\u0003אמר רב חסדא אמר רב חמא בר גוריא אמר רב: הלכה כר' אלעזר בגיטין.\u0004 שאת רב חסדא ראה רבה בר רב הונא כחבירו, ואילו לרב חמא בר גוריא התייחס כתלמידו של רב.","\u0003וכן כי אתא\u0004 \u0005[כאשר בא]\u0006 \u0003רבין,\u0004 \u0003אמר ר' אלעזר אמר רב: הלכה כ\u0004שיטת \u0003ר' אלעזר בגיטין.\u0004","\u0003שנים ששלחו שני גיטין שוין,\u0004 שהיו שמותיהם ושמות נשיהם שווים זה לזה \u0003ונתערבו\u0004 שני הגיטין, \u0003נותן\u0004 השליח \u0003שניהם ל\u0004אשה \u0003זו ושניהם לזו\u0004 ואז ברור שכל אחת מהן קיבלה את גיטה, אף שלא ברור לנו איזה הוא. \u0003לפיכך,\u0004 אם \u0003אבד אחד מהן\u0004 לפני שניתן לשתי הנשים — \u0003הרי השני בטל,\u0004 שהרי לא ידוע של מי מהן הוא.","\u0003חמשה שכתבו כלל בתוך הגט,\u0004 שכתבו את גיטיהם בדף אחד בנוסח כללי, כלומר, \u0003איש פלוני מגרש\u0004 את \u0003פלונית, ופלוני\u0004 את \u0003פלונית, והעדים\u0004 חתומים \u0003מלמטה\u0004 — כל הגיטין הללו הכתובים יחד \u0003כולן כשרין, וינתן\u0004 שטר זה לכל אחת ואחת בפני עצמה, והיא מגורשת בו. אם \u0003היה\u0004","\u0003כותב טופס\u0004 נפרד של גט \u0003לכל אחד ואחד\u0004 מהגיטין הללו הכתובים בשטר אחד, \u0003והעדים\u0004 חתומים \u0003מלמטה, את\u0004 אותו גט \u0003שהעדים ניקרין\u0004 (נקראין) \u0003עמו\u0004 שחתימתם סמוכה לו — הוא \u0003כשר,\u0004 והאחרים פסולים.","שואלים: \u0003מאן\u0004 \u0005[מיהו]\u0006 ה\u0003תנא\u0004 ששונה זאת? \u0003אמר ר' ירמיה:\u0004 ש\u0003לא כ\u0004שיטת \u0003ר' אלעזר, דאי\u0004 \u0005[שאם]\u0006 כשיטת \u0003ר' אלעזר, כיון\u0004 ש\u0003אמר עדי מסירה כרתי\u0004 \u0005[\u0006הם ש\u0005כורתים]\u0006 ועל ידם נעשה עיקר הגט, \u0003הא לא ידעי בהי מינייהו קא מגרשה\u0004 \u0005[הרי אינם יודעים\u0006 בשעת מסירה \u0005באיזה מהם היא מתגרשת]\u0006 ונמצא שעיקר הגירושין (ה\"כריתות\") בשעת מסירה לא נעשה כראוי.","\u0003אביי אמר: אפילו תימא\u0004 \u0005[תאמר]\u0006 שהוא כשיטת \u0003ר' אלעזר, אימא דבעי\u0004 \u0005[אמור שצריך]\u0006 \u0003ר' אלעזר\u0004 שתהיה \u0003כתיבה לשמה,\u0004 אבל \u0003נתינה לשמה מי בעי\u0004 \u0005[האם הוא צריך]?\u0006 שאמנם סבור הוא שהנתינהמסירה היא הקובעת, אבל לא אמר שהנתינה צריכה להיות לשמה, והרי כאן מכל מקום נמסר הגט לאשה.","שנינו במשנה בענין הגט: \u0003חמשה שכתבו כלל\u0004 — הרי כולן מתגרשות בו, וחמישה שכתבו טופס נפרד לכל אחד כשר רק האחרון. ושואלים: \u0003היכי דמי\u0004 \u0005[כיצד הוא בדיוק]\u0006 \u0003כלל, היכי דמי\u0004 \u0005[כיצד הוא בדיוק]\u0006 \u0003טופס\u0004 לכל אחד ואחד?","\u0003אמר ר' יוחנן:\u0004 אם היה \u0003זמן אחד לכולן,\u0004 שהיה תאריך אחד וכן נוסח אחד של הגט לכולם, כגון שכתב: \"בתאריך פלוני גירש פלוני את פלונית, ופלוני את פלונית, וכן אמר כל אחד מהם לאשתו\" וכו' — \u0003זהו כלל.\u0004 אם היה \u0003זמן\u0004 וכל נוסח הגט כתוב \u0003לכל אחד ואחד\u0004 — \u0003זהו\u0004 הנקרא \u0003טופס\u0004 נפרד.","\u0003וריש לקיש אמר:\u0004"],["\u0003אפילו זמן אחד לכולן נמי\u0004 \u0005[גם כן]\u0006 \u0003הוי\u0004 \u0005[הריהו]\u0006 \u0003טופס,\u0004 שכיון שהזכיר שפלוני גירש את פלונית ופלוני את פלונית כל אחד לעצמו — הריהם כטפסים נבדלים, \u0003אלא היכי דמי\u0004 \u0005[כיצד הוא בדיוק]\u0006 \u0003כלל\u0004 — ש\u0003כתב\u0004 בו כך: \u0003\"אנו פלוני ופלוני גירשנו נשותינו פלונית ופלונית\"\u0004 שאין גירושי כל זוג נזכרים לעצמם בגט.","\u0003מתקיף לה\u0004 \u0005[מקשה על כך]\u0006 \u0003ר' אבא: ל\u0004שיטת \u0003ר' יוחנן,\u0004 ש\u0003אמר זמן אחד לכולן זהו כלל, ליחוש\u0004 \u0005[שנחשוש]\u0006 אם כן \u0003דלמא כי\u0004 \u0005[שמא כאשר]\u0006 \u0003חתמו סהדי\u0004 \u0005[העדים]\u0006 — \u0003אבתרא\u0004 \u0005[על\u0006 הזוג \u0005האחרון]\u0006 בלבד \u0003הוא דחתימי\u0004 \u0005[שחתמו]!\u0006 \u0003מי\u0004 \u0005[האם]\u0006 \u0003לא תניא\u0004 \u0005[שנינו\u0006 בברייתא\u0005]:\u0006 \u0003עדים חתומין על שאילת שלום בגט,\u0004 שלאחר נוסח הגט היה כתוב בו שידרשו בשלום מישהו — הרי זה \u0003פסול,\u0004 ומדוע? — \u0003חיישינן\u0004 \u0005[חוששים אנו]\u0006 \u0003שמא על שאילת שלום חתמו,\u0004 ולא על הגט!","ודוחים: \u0003לאו איתמר עלה\u0004 \u0005[\u0006וכי \u0005לא נאמר עליה\u0006 על ברייתא זו\u0005]:\u0006 \u0003אמר ר' אבהו, לדידי מפרשא לי מיניה\u0004 \u0005[לי עצמי נתפרש לי\u0006 הדבר \u0005ממנו]\u0006 מ\u0003ר' יוחנן\u0004 אם היה כתוב בסוף הגט \u0003\"שאלו\u0004 בשלום פלוני \u0003\"\u0004— הרי זה \u0003פסול,\u0004 שכאן מתחיל ענין חדש, ושמא חתמו העדים רק על שאילת השלום, אבל אם כתוב \u0003\"ושאלו\"\u0004 בו\"ו החיבור, שנראה שהוא המשך של הדברים הקודמים, ועל הכל חתמו העדים — הרי זה \u0003כשר. הכא נמי\u0004 \u0005[כאן גם כן]\u0006 יש לפרש \u0003דכתיב ביה\u0004 \u0005[שכתוב בו]\u0006 בגט זה \u0003\"פלוני\u0004 גרש את פלונית \u0003ופלוני\u0004 גרש את פלונית \u0003ופלוני\u0004 גרש את פלונית","\u0003\"\u0004בו\"ו החיבור, שרואים שיש כאן המשך. ושואלים: \u0003ותו\u0004 \u0005[ועוד]\u0006 יש להקשות: \u0003לר' יוחנן,\u0004 ש\u0003אמר זמן לכל אחד זהו טופס, מאי איריא\u0004 \u0005[מה שייך,\u0006 מדוע דווקא\u0005]\u0006 \u0003משום טופס\u0004 מיוחד שבו? \u0003ותיפוק ליה\u0004 \u0005[ותצא לו]\u0006 פסילת הגט הזה מטעם אחר, \u0003דהוה ליה\u0004 \u0005[שהרי הוא]\u0006 כגט ש\u0003נכתב ביום ונחתם בלילה\u0004 שהוא פסול. שאנו מבינים שכל גט נכתב בזמן אחר וחתימת העדים נעשתה רק לאחר שנכתב הגט האחרון, ואם כן שאר הגיטין שנכתבו קודם לכן לא נחתמו בזמן שנכתבו!","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003מר קשישא\u0004 \u0005[הזקן]\u0006 \u0003בריה\u0004 \u0005[בנו]\u0006 של \u0003רב חסדא לרב אשי,\u0004 \u0003הכי אמרינן\u0004 \u0005[כך אנו אומרים]\u0006 \u0003משמיה\u0004 \u0005[משמו]\u0006 של \u0003ר' יוחנן\u0004 בהסבר הלכה זו: כגון \u0003דכתיב בהו\u0004 \u0005[שכתוב בהם]\u0006 בכל אחד מהם \u0003בחד בשבא\u0004 \u0005[בראשון בשבת],\u0006 \u0003בחד בשבא\u0004 \u0005[בראשון בשבת],\u0006 כלומר, שהזמן המפורש בתוך כל גט הוא אותו זמן, ונמצא שנכתבו כולם באותו יום.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבינא לרב אשי: ל\u0004דעת \u0003ריש לקיש,\u0004 ש\u0003אמר\u0004 שאם נזכרו גירושין של כל זוג לעצמו, אף ש\u0003זמן אחד לכולן נמי\u0004 \u0005[גם כן]\u0006 \u0003טופס\u0004 לכל אחד ואחד \u0003הוי\u0004 \u0005[הוא\u0006 נחשב\u0005],\u0006 \u0003והיכי דמי\u0004 \u0005[וכיצד הוא בדיוק]\u0006 \u0003כלל\u0004 — \u0003דכתיב ביה הכי\u0004 \u0005[שכתוב בו כך]\u0006 \u0003\"אנו פלוני ופלוני גירשנו נשותינו פלונית ופלונית\",\u0004 אם כן \u0003נמצאו שתי נשים מתגרשות בגט אחד\u0004 שהרי כל אותן נשים מתגרשות באותו שטר עצמו שיש בו רשימה של שמות, \u0003והתורה אמרה: \"וכתב לה\"\u0004 (דברים כד, א) ולמדנו מכאן: \u0003ולא לה ולחברתה!\u0004 וכל אחת צריכה גט מיוחד לעצמה!","ומשיבים: \u0003דהדר\u0004 \u0005[שחזר]\u0006 ו\u0003כתב\u0004 כך לאחר הנוסח הכללי: \u0003פלוני גירש\u0004 את \u0003פלונית, ופלוני גירש\u0004 את \u0003פלונית.\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבינא לרב אשי: ומאי שנא מהא דתניא\u0004 \u0005[ומה שונה\u0006 הדבר \u0005מזו ששנינו\u0006 בברייתא\u0005]:\u0006 \u0003הכותב כל נכסיו לשני עבדיו\u0004 — \u0003קנו\u0004 שניהם את הנכסים \u0003ומשחררין זה את זה,\u0004 שהרי כל אחד מהם הוא בכלל הנכסים, ונמצא שחציו משועבד לחבירו, ולכן צריכים לשחרר זה את זה. וכיון שבהלכה הושוו שיחרורי עבדים לגיטי נשים, יכולים אנו ללמוד מכאן ששטר אחד הנכתב לשנים כאחד — מועיל!","ודוחים: \u0003ולאו אוקימנא\u0004 \u0005[וכי לא העמדנו\u0006 את הדבר\u0005]\u0006 שמדובר שכתב זאת \u0003בשני שטרות\u0004 ולא בשטר אחד? שכתב לכל עבד שנותן לו כל נכסיו, ונתן לשניהם את השטרות בבת אחת. ואם כן אף בשיחרור עבדים צריך שטר לכל אחד לעצמו.","ומעירים: \u0003תניא כוותיה\u0004 \u0005[שנויה\u0006 ברייתא \u0005כשיטתו]\u0006 של \u0003ר' יוחנן,\u0004 וכן \u0003תניא כוותיה\u0004 \u0005[שנויה\u0006 ברייתא \u0005כשיטתו]\u0006 של \u0003ריש לקיש.\u0004","\u0003תניא כוותיה\u0004 \u0005[שנויה\u0006 ברייתא \u0005כשיטתו]\u0006 של \u0003ר' יוחנן:\u0004 \u0003חמשה שכתבו בתוך הגט \"איש פלוני מגרש\u0004 את \u0003פלונית, ופלוני\u0004 את \u0003פלונית, ופלוני\u0004 את \u0003פלונית\", וזמן אחד לכולן, והעדים\u0004 חתומים \u0003מלמטה\u0004 — \u0003כולן כשרים, ותנתן\u0004 התעודה הזו \u0003לכל אחת ואחת\u0004 ותתגרש בה.","ואם היה כתוב \u0003זמן לכל אחד ואחד והעדים מלמטה, את\u0004 (אותו גט) \u0003שהעדים נקראים עמו\u0004 — \u0003כשר. ר' יהודה בן בתירא אומר:\u0004 \u0003אם יש ריוח ביניהן\u0004 — \u0003פסול,\u0004 שנראה שחתימת העדים היא על האחרון בלבד, \u0003ואם לאו\u0004 \u0005[לא]\u0006 — \u0003כשר,\u0004 שלדעתו \u0003אין\u0004 ה\u0003זמן\u0004 שכתוב בהם, כל זוג לעצמו, \u0003מפסיקן,\u0004 אלא הם נחשבים כשטר אחד.","\u0003תניא כוותיה\u0004 \u0005[שנויה\u0006 ברייתא \u0005כשיטתו]\u0006 של \u0003ריש לקיש:\u0004 \u0003חמשה שכתבו כלל בתוך הגט, \"אנו פלוני ופלוני גירשנו נשותינו פלונית ופלונית, פלוני גירש\u0004 את \u0003פלונית ופלוני גירש\u0004 את \u0003פלונית\", וזמן אחד לכולן והעדים\u0004 חתומים \u0003מלמטה\u0004 — \u0003כולן כשרין, ותנתן לכל אחת ואחת.\u0004","ואם היה \u0003זמן לכל אחד ואחד, וריוח לכל אחד ואחד, והעדים מלמטה, את שהעדים נקראין עמו\u0004 — הרי זה \u0003כשר\u0004 ולא אחרים. \u0003ר' מאיר אומר: אף על פי שאין ריוח ביניהם\u0004 — \u0003פסול,\u0004 לפי \u0003שהזמן מפסיקן.\u0004","ושואלים: \u0003ו\u0004לדעת \u0003ריש לקיש, מאי איריא\u0004 \u0005[מה שייך],\u0006 מדוע הודגש שם \u0003זמן לכל אחד ואחד? הא\u0004 \u0005[הרי]\u0006 הוא \u0003אמר:\u0004 \u0003זמן אחד לכולן נמי\u0004 \u0005[גם כן]\u0006 \u0003טופס\u0004 נפרד לכל אחד ואחד \u0003הוי\u0004 \u0005[הריהו\u0006 נחשב\u0005]!\u0006","ומשיבים: \u0003הני מילי\u0004 \u0005[דברים אלה]\u0006 אמורים \u0003היכא\u0004 \u0005[במקום]\u0006 \u0003לא ערבינהו מעיקרא\u0004 \u0005[עירב אותם מתחילה]\u0006 אלא כתב כל אחד לעצמו. \u0003אבל הכא\u0004 \u0005[כאן]\u0006 \u0003דערבינהו מעיקרא\u0004 \u0005[שעירב אותם מתחילה]\u0006 וכתב בנוסח: \"פלוני ופלוני מגרשים את נשותיהם פלונית ופלונית\", \u0003אי פליג להו\u0004 \u0005[אם חולק להם]\u0006 \u0003זמן\u0004 לכל אחד ואחד — \u0003אין\u0004 \u0005[כן]\u0006 הרי הם נחשבים לשטרות חלוקים, \u0003אי\u0004 \u0005[אם]\u0006 \u0003לא\u0004 — \u0003לא\u0004 נחשבים לחלוקים.","\u0003שני גיטין שכתבן זה בצד זה\u0004 על אותו קלף או נייר, \u0003ושנים עדים עברים,\u0004 כלומר, שכותבים בעברית מימין לשמאל \u0003באים,\u0004 כלומר, חתימתם הולכת \u0003מתחת\u0004 גט \u0003זה\u0004 הימני \u0003לתחת\u0004 גט \u0003זה\u0004 השמאלי, \u0003ושנים עדים יונים\u0004 שכותבים משמאל לימין \u0003באים מתחת זה\u0004 השמאלי \u0003לתחת זה\u0004 הימני, \u0003את\u0004 (גט זה) \u0003ש\u0004שמות \u0003העדים הראשונים נקראין עמו\u0004 בצמוד אליו, הוא ה\u0003כשר.\u0004","אם היה \u0003עד אחד עברי\u0004 שכותב מימין לשמאל \u0003ו\u0004מתחתיו \u0003עד אחד יוני\u0004 שכותב משמאל לימין, \u0003ו\u0004אחריהם \u0003עד אחד עברי\u0004 ומתחתיו עד \u0003אחד יוני, באין מתחת\u0004 גט \u0003זה לתחת\u0004 גט \u0003זה — שניהם,\u0004 שני הגיטין \u0003פסולין.\u0004","שנינו במשנה שאם היו החתימות עוברות מתחת לשני הגיטין הרי רק זה שצמודים אליו שמות העדים כשר, לפי שאין חתימה על הגט השני, ושואלים: \u0003וליתכשר\u0004 \u0005[ושיהיה כשר]\u0006 \u0003האי\u0004 \u0005[\u0006גט \u0005זה]\u0006 הראשון \u0003ב\u0004מה שיש בו חתימת \u0003ראובן\u0004 בלבד, \u0003והאי\u0004 \u0005[וזה],\u0006 הגט השני יהיה כשר \u0003ב\u0004מה שכתוב בהמשך \u0003\"בן יעקב עד\",\u0004 ונאמר שזוהי חתימה אחרת על הגט השני, וכן העד החתום תחתיו, \u0003דהא תנן\u0004 \u0005[שהרי שנינו\u0006 במשנה\u0005]\u0006 להלן: אם חתם העד רק \u0003\"בן איש פלוני עד\"\u0004 — הרי זה \u0003כשר!\u0004","ומשיבים: מדובר \u0003דכתב\u0004 \u0005[שכתוב\u0006 בו\u0005]\u0006 כך: \u0003\"ראובן בן\" אקמא\u0004 \u0005[על\u0006 הגט \u0005הראשון,\u0006 הימני\u0005]\u0006 \u0003ו\"יעקב עד\" אבתרא\u0004 \u0005[על האחרון,\u0006 השמאלי\u0005]\u0006 שאז מסתבר שחתימה אחת היא ולא שנים.","ומקשים: \u0003וליתכשר האי\u0004 \u0005[ושיהיה כשר\u0006 גט \u0005זה,\u0006 השמאלי\u0005]\u0006 \u0003ב\"ראובן בן\", וליתכשר האי\u0004 \u0005[ושיהיה כשר\u0006 גט \u0005זה,\u0006 הימני\u0005]\u0006 \u0003ב\"יעקב עד\", דהא תנן\u0004 \u0005[שהרי שנינו\u0006 במשנה\u0005]\u0006 להלן: אם כתוב רק \u0003\"איש פלוני עד\"\u0004 בלי שיכתוב שם אביו — הרי זה \u0003כשר!\u0004","ומשיבים: ש\u0003לא כתב\u0004 \u0005[כתוב]\u0006 תחת השמאלי \u0003\"עד\",\u0004 אלא שם בלבד, ואין די בזה. \u0003ואיבעית אימא\u0004 \u0005[ואם תרצה אמור]:\u0006 \u0003לעולם\u0004 ש\u0003כתב \"עד\"\u0004 שהיה כתוב תחת השמאלי \"יעקב עד\", \u0003ו\u0004אולם מדובר \u0003דידעינן בהא חתימה דלאו דיעקב הוא\u0004 \u0005[שיודעים אנו שחתימה זו שלא של יעקב היא]\u0006 ומסתבר שחתימה זו היא חלק מחתימתו של ראובן בן יעקב, ואי אפשר לסמוך עליה כחתימה נפרדת לגט שני."],["ושואלים: \u0003ודלמא בשמא דאבוה חתים\u0004 \u0005[ושמא בשם אביו חתם]\u0006 שבאמת ראובן הוא שחתם, אלא שחתם בשם אביו על הגט השני! ודוחים: \u0003לא שביק איניש שמיה וחתים שמא דאבוה\u0004 \u0005[אין אדם מניח את שמו וחותם את שם אביו].\u0006","ושואלים: \u0003ודילמא סימנא שוייה\u0004 \u0005[ושמא סימן עשה אותו],\u0006 את שם אביו, שאף שאינו חותם בשם אביו הריהו משתמש בשם אביו כבסימן במקום חתימה. \u0003דהא\u0004 \u0005[שהרי]\u0006 \u0003רב\u0004 במקום חתימה \u0003צייר כוורא\u0004 \u0005[היה מצייר דג],\u0006 \u0003ר' חנינא\u0004 היה מצייר \u0003חרותא\u0004 \u0005[דקל],\u0006 \u0003רב חסדא\u0004 — \u0003סמ\"ך, רב הושעיא\u0004 — \u0003עי\"ן, רבה בר רב הונא צייר מכותא\u0004 \u0005[היה מצייר מפרש]!\u0006","ומשיבים: \u0003לא חציף איניש לשויי לשמא דאבוה סימנא\u0004 \u0005[אין אדם מתחצף לעשות את שם אביו כסימן]\u0006 ולכן אנחנו מניחים שזה המשך של שמו, אבל אין נוסח זה מספיק כדי להיחשב כחתימה על הגט השני.","ומקשים מצד אחר: \u0003וליתכשר האי\u0004 \u0005[ושיהיה כשר זה],\u0006 הגט הראשון \u0003בשני עדים עברים, וליתכשר האי\u0004 \u0005[ושיהיה כשר זה]\u0006 הגט השני \u0003בשני עדים יונים, דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]\u0006 להלן: \u0003גט שכתבו עברית ועדיו\u0004 חתומים \u0003יונית,\u0004 או כתבו \u0003יונית ועדיו\u0004 חתומים \u0003עברית\u0004 — הרי זה \u0003כשר!\u0004","\u0003וכי תימא\u0004 \u0005[ואם תאמר],\u0006 \u0003כיון דמופלג\u0004 \u0005[שמרוחק]\u0006 הגט השני מעדיו \u0003בשני שיטין\u0004 \u0005[בשתי שורות]\u0006 \u0003לא\u0004 יהא כשר, ככל שטר שעדיו מרוחקים ממנו. \u0003ו\u0004אולם \u0003האמר\u0004 \u0005[הרי אמר]\u0006 \u0003חזקיה:\u0004 אם \u0003מלאהו\u0004 לאותו רווח שבין הגט לעדיו, אף \u0003בקרובים\u0004 הפסולים לעדות — הרי זה \u0003כשר,\u0004 ואין אומרים שהפסקה זו פוסלת!","ומשיבים: אכן, \u0003הא תני\u0004 \u0005[הרי שנה]\u0006 \u0003זעירי: שניהן,\u0004 שני הגיטין\u0003, כשרים,\u0004 ולא רק זה שהעדים סמוכים לו. ושואלים: \u0003ו\u0004ה\u0003תנא דידן\u0004 \u0005[שלנו]\u0006 שאיננו אומר כן, מה סבור הוא? ומשיבים: הוא חושש \u0003דלמא גונדלית חתים\u0004 \u0005[שמא במהופך חתמו],\u0006 שהעדים היוונים הפכו את סדר המילים בחתימתם, ובאמת כל החתימות מתייחסות לגט הראשון, \u0003וכולהו אחד הוא דחתימי\u0004 \u0005[וכולם על\u0006 גט \u0005אחד\u0006 הוא \u0005שחתמו].\u0006","שנינו במשנה שהיו חתומים על הגט \u0003עד אחד עברי ועד אחד יוני\u0004 ועד אחד עברי ועד אחד יווני — שניהם פסולים. ושואלים: \u0003וליתכשר האי\u0004 \u0005[ושיהיה כשר\u0006 גט \u0005זה]\u0006 \u0003בעד אחד עברי ועד אחד יוני, והאי\u0004 \u0005[ו\u0006גט \u0005זה]\u0006 \u0003בעד אחד עברי ועד אחד יוני, דהא תנן\u0004 \u0005[שהרי שנינו\u0006 במשנה\u0005]:\u0006 \u0003עד אחד עברי ועד אחד יוני\u0004 — \u0003כשר!\u0004","ואומרים: אכן, \u0003הא תני\u0004 \u0005[הרי שנה]\u0006 \u0003זעירי: שניהם כשרים.\u0004 ושואלים: \u0003ו\u0004ה\u0003תנא דידן\u0004 \u0005[שלנו]\u0006 שפוסל, מה הוא סבור? ומשיבים: \u0003דלמא גונדלית חתים\u0004 \u0005[שמא במהופך חתמו],\u0006 שהעד היווני הראשון הפך את סדר חתימתו, ובאמת הוא חתום על הגט השני \u0003ו\u0004נמצא \u0003תלתא אחד\u0004 \u0005[שלושה\u0006 חתמו \u0005על\u0006 גט \u0005אחד],\u0006 \u0003וחד אחד\u0004 \u0005[ואחד\u0006 בלבד חתם על גט \u0005אחד],\u0006 ולכן אינו כשר.","\u0003שייר\u0004 כותב הגט \u0003מקצת הגט\u0004 ולא כתבו כולו בדף אחד \u0003וכתבו בדף השני,\u0004 כלומר, בטור שני על אותו נייר, \u0003והעדים\u0004 חתומים \u0003מלמטה\u0004 בדף השני — הרי זה גט \u0003כשר.\u0004 אם \u0003חתמו עדים בראש הדף\u0004 או \u0003מן הצד, או מאחריו,\u0004 אם היה זה \u0003בגט פשוט\u0004 — הרי זה \u0003פסול.\u0004","אם \u0003הקיף\u0004 \u0005[הצמיד]\u0006 \u0003ראשו של\u0004 גט \u0003זה בצד ראשו של זה,\u0004 שהיו שני גיטין כתובים על דף אחד במהופך \u0003והעדים\u0004 חתומים \u0003באמצע\u0004 בין הגיטין — \u0003שניהם,\u0004 שני הגיטין, \u0003פסולין.\u0004 אם היה \u0003סופו של זה בצד סופו של זה והעדים באמצע, את\u0004 (אותו) גט \u0003שהעדים נקרין\u0004 (נקראים) \u0003עמו,\u0004 שחתימתם כתובה באופן שהיא נקראת כהמשך שלו — \u0003כשר.\u0004 היה \u0003ראשו של\u0004 גט \u0003זה בצד סופו של זה והעדים\u0004 חתומים \u0003באמצע\u0004 בין שני הגיטין, \u0003את שהעדים נקרין בסופו\u0004 (כלומר, גט ראשון) — \u0003כשר.\u0004","\u0003גט שכתבו עברית ועדיו\u0004 חתומים בכתב \u0003יוונית,\u0004 או כתבו \u0003יוונית ועדיו עברית,\u0004 או \u0003עד אחד\u0004 חתום בכתב \u0003עברי ועד אחד יווני,\u0004 או היה \u0003כתב סופר\u0004 שמזהים על פי כתב ידו \u0003ו\u0004עוד חתימת \u0003עד\u0004 הרי זה \u0003כשר.\u0004","ובאופני חתימת העדים, אם היה חתום \u0003\"איש פלוני עד\"\u0004 ולא כתב את שם אביו — הרי זה \u0003כשר.\u0004 וכן אם לא כתב שמו הפרטי אלא \u0003\"בן איש פלוני עד\"\u0004 בלבד — \u0003כשר.\u0004 או כתב \u0003\"איש פלוני בן איש פלוני\" ולא כתב \"עד\"\u0004 — \u0003כשר. וכך היו נקיי הדעת שבירושלים עושין,\u0004 שלא היו חותמים \"עד\". ועוד בענין שמות בגט, \u0003כתב חניכתו\u0004 (שם משפחתו או כינויו) של הבעל \u0003וחניכתה\u0004 (שם משפחתה או כינויה) של האשה המתגרשת — \u0003כשר.\u0004","על האמור במשנה בדבר גט הכתוב בשני דפים, שהוא כשר, שואלים: \u0003וליחוש\u0004 \u0005[ונחשוש]\u0006 \u0003דלמא הני תרי גיטי הוו\u0004 \u0005[שמא שני גיטין היו אלה בתחילתם]\u0006 זה בצד זה, השני גבוה מן הראשון, \u0003ואיתרמי ליה\u0004 \u0005[והזדמן לו]\u0006 שמקומו של ה\u0003זמן דקמא\u0004 \u0005[של\u0006 הגט \u0005הראשון]\u0006 שהוא בתחילת הגט, \u0003ועדים דבתרא\u0004 \u0005[של\u0006 הגט \u0005האחרון]\u0006 שהוא בסוף הגט, נמצאים זה בצד זה, \u0003וגזייה לזמן דבתרא\u0004 \u0005[וחתך את הזמן של\u0006 הגט \u0005האחרון]\u0006 \u0003ועדים דקמא\u0004 \u0005[של\u0006 הגט \u0005הראשון]\u0006 עד ששני חלקי הגיטין נראים כגט אחד המתפרס על שתי עמודות!","\u0003אמר רב אבא אמר רב:\u0004 מדובר \u0003כשיש ריוח מלמטה\u0004 וברור שלא גזר את סוף הגט הראשון. ושואלים: \u0003ודלמא\u0004 \u0005[ושמא]\u0006 את ה\u0003זמן,\u0004 חלקו העליון \u0003דבתרא מיגז גזייה\u0004 \u0005[של\u0006 הגט \u0005האחרון, גזז אותו]\u0006 ונמצא החלק האחרון כהמשך של חלק מן הגט הראשון שעדיין לא סיים לכותבו! ומשיבים: \u0003כדאמר\u0004 \u0005[כמו שאמר]\u0006 \u0003ר' אבא אמר רב: כשיש ריוח מלמטה,\u0004"],["\u0003הכא נמי\u0004 \u0005[כאן גם כן]\u0006 יש לומר שמדובר \u0003כשיש ריוח מלמעלה,\u0004 שרואים שזו היא תחילת הגט.","ושואלים עוד על האמור במשנה בגט הכתוב בשני דפים שהוא כשר: \u0003ו\u0004נחשוש \u0003דלמא\u0004 \u0005[שמא]\u0006 מדובר כאן שכתב מקצת הגט ואחרי כן \u0003אימלוכי אימליך\u0004 \u0005[נמלך\u0006 בדעתו, התחרט\u0005]\u0006 על כך וביטלו, ואחר כך שוב נמלך בדעתו \u0003וכתב\u0004 את הגט עד סופו בדף השני, כך שחלקו הראשון כבר נפסל על ידי ביטולו!","ומשיבים: מדובר כגון ש\u0003כתב \"הרי את\" מלמטה\u0004 בתחתית הדף הראשון \u0003ו\u0004את המשך המשפט \u0003\"מותרת\"\u0004 כתב \u0003מלמעלה,\u0004 בתחילת הדף השני, שרואים שיש המשך ורצף בין שני הדפים ובוודאי לא נמלך בדעתו בין זה לזה. ושואלים: \u0003ודלמא איתרמי ליה\u0004 \u0005[ושמא הזדמן לו]\u0006 במקרה שהפסיק באמצע משפט? ומשיבים: \u0003כולי האי לא חיישינן\u0004 \u0005[כל כך אין אנו חוששים].\u0006","\u0003רב אשי א\u0004 \u0003מר:\u0004 במשנתנו מדובר \u0003דידיעה ביה מתחתא דמגילתא\u0004 \u0005[שניכרת בו מתיחת הקלף]\u0006 וניכר מן הקלף שהיתה זו חתיכה אחת ולא נחתך ממנה דבר.","שנינו במשנה: \u0003חתמו עדים בראש הדף\u0004 או בצידו — הגט פסול. ומקשים: \u0003איני\u0004 \u0005[כן הוא]?\u0006 \u0003והא\u0004 \u0005[והרי]\u0006 \u0003רב חתים\u0004 \u0005[\u0006היה \u0005חותם]\u0006 \u0003מן הצד!\u0004 ומשיבים: \u0003התם\u0004 \u0005[שם]\u0006 במה שמסופר על רב מדובר \u0003בשגגו,\u0004 צידו העליון, של כתב העדים \u0003כלפי כתב\u0004 הגט, שניכר שעל כך הוא חותם.","ומקשים: \u0003אלא הא דקתני\u0004 \u0005[זה ששנה]\u0006 במשנתנו: \u0003הקיף\u0004 \u0005[הצמיד]\u0006 \u0003ראשו של\u0004 גט \u0003זה בצד ראשו של זה,\u0004 שהיו שני גיטין כתובים על דף אחד במהופך \u0003והעדים\u0004 חתומים \u0003באמצע\u0004 בין הגיטין — \u0003שניהם\u0004 שני הגיטין \u0003פסולין, וליחזי הי מינייהו\u0004 \u0005[ונראה איזה מהם]\u0006 עומד כשגג חתימות העדים \u0003כלפי כתב, וליתכשר\u0004 \u0005[ויהיה כשר]!\u0006","ומשיבים: \u0003התם\u0004 \u0005[שם]\u0006 במשנה, מדובר \u0003דרמי ליה כעיברא\u0004 \u0005[שמונח לו כבריח]\u0006 שלא חתמו העדים במאוזן בין שני הגיטין, אלא במאונך, שאין חתימתם מהווה רצף של אף אחד מן הגיטין.","ומקשים: \u0003אי הכי, סיפא דקתני\u0004 \u0005[אם כך, בסוף ששנה]\u0006 \u0003ראשו של זה בצד סופו של זה והעדים\u0004 חתומים \u0003באמצע, את\u0004 (אותו גט) \u0003שהעדים ניקרין בסופו\u0004 — \u0003כשר. ואי דרמי כעיברא\u0004 \u0005[ואם\u0006 מדובר במשנה \u0005שמונח\u0006 כתב העדים \u0005כבריח]\u0006 שהוא במאונך, \u0003לאו בהדי האי מיקרי ולאו בהדי האי מיקרי\u0004 \u0005[לא יחד עם\u0006 גט \u0005זה\u0006 הוא \u0005נקרא ולא יחד עם\u0006 גט \u0005זה\u0006 הוא \u0005נקרא]!\u0006","\u0003אלא\u0004 יש לדחות מה שהסברנו, ולומר כי \u0003רב בדיסקי הוה חתים\u0004 \u0005[במכתבים\u0006 או בפסקים \u0005היה חותם\u0006 מן הצד\u0005]\u0006 שאין הקפדה בדבר, אבל לענין גט ושאר שטרות יש להקפיד שתהא החתימה דווקא מתחת לכתב.","שנינו במשנה: \u0003\"גט שכתבו עברית וכו', כתב סופר ועד\u0004 — \u0003כשר\". אמר ר' ירמיה: חתם סופר שנינו,\u0004 שאין סומכים על כך שמכירים את כתב הסופר להכשיר את הגט, אלא אם כן היה הסופר חתום כעד נוסף בשטר.","\u0003אמר רב חסדא: הא מני\u0004 \u0005[\u0006משנתנו \u0005זו כ\u0006שיטת \u0005מי היא]?\u0006 — כשיטת \u0003ר' יוסי היא\u0004 שאין אנו חוששים שמא חתם הסופר שלא כדין.","מסופר: \u0003ההיא כתובת חתנים דאתיא לקמיה\u0004 \u0005[כתובה של חתן שהובאה לפני]\u0006 \u0003ר' אבהו\u0004 לדון בה, \u0003דהוו ידעי ליה לטופסא\u0004 \u0005[שהיו מכירים את הטופס],\u0006 כלומר, הכירו והעידו על כתב היד של הסופר \u0003ולחתימת ידא דחד סהדא\u0004 \u0005[ועל חתימת ידו של עד אחד],\u0006 \u0003סבר לאכשורה\u0004 \u0005[חשב\u0006 ר' אבהו \u0005להכשיר אותה]\u0006 על ידי כתב סופר ועד, \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003ר' ירמיה: חתם סופר שנינו,\u0004 וכתבו לבד אינו מספיק.","שנינו במשנה: \u0003כתב\u0004 בגט \u0003חניכתו,\u0004 כינוי או שם משפחה של המגרש \u0003וחניכתה\u0004 של האשה — \u0003כשר. תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 מי שכתב \u0003חניכת אבות\u0004 שלו \u0003בגיטין\u0004 כשר \u0003עד עשרה דורות,\u0004 שעדיין יכול הוא להתייחס לשם או לכינוי זה. \u0003ר' שמעון בן אלעזר אומר: שלשה דורות\u0004 — \u0003כשר, מכאן ואילך\u0004 — \u0003פסול.\u0004","ומעירים: \u0003כמאן אזלא\u0004 \u0005[כ\u0006שיטת \u0005מי הולכת]\u0006 \u0003הא דאמר\u0004 \u0005[זו שאמר]\u0006 \u0003ר' חנינא: כתב חניכת אבות בגיטין עד שלשה דורות, כמאן\u0004 \u0005[כ\u0006שיטת \u0005מי]\u0006 — \u0003כ\u0004שיטת \u0003ר' שמעון בן אלעזר.\u0004","\u0003אמר רב הונא: מאי קראה\u0004 \u0005[מהו הכתוב]\u0006 המרמז על כך? — שנאמר: \u0003\"כי תוליד בנים ובני בנים ונושנתם\"\u0004 (דברים ד, כה), כלומר, לאחר \"בני בנים\", שהם שלושה דורות, הדבר כבר נקרא ישן.","ואגב הסברת פסוק זה מביאים עוד דברים עליו. \u0003אמר ר' יהושע בן לוי: לא חרבה ארץ ישראל\u0004 חורבן ראשון \u0003עד שעבדו בה שבעה בתי דינים עבודה זרה,\u0004 שבמשך זמן שלטונם של שבע שושלות מלכים היו גם מנהיגי ישראל ודייניו עובדי עבודה זרה, \u0003ואלו הן: ירבעם בן נבט, ובעשא בן אחיה, ואחאב בן עמרי, ויהוא בן נמשי, ופקח בן רמליהו, ומנחם בן גדי, והושע בן אלה. שנאמר: \"אמללה ילדת השבעה נפחה נפשה באה שמשה בעוד יומם בושה וחפרה\"\u0004 (ירמיהו טו, ט).","\u0003אמר רב אמי: מאי קראה\u0004 \u0005[מהו הכתוב]\u0006 המרמז על כך — \u0003\"כי תוליד בנים ובני בנים\u0004 ונושנתם\u0003\"\u0004(דברים ד, כה) שהוא מפרש \"כי תוליד\" — דור אחד, \"בנים\" — הרי שנים, \"ובני\" — שנים, \"בנים\" — שנים, הרי שבעה דורות רמוזים.","\u0003אמרו ליה\u0004 \u0005[לו]\u0006 \u0003רב כהנא ורב אסי לרב: כתיב ביה\u0004 \u0005[נאמר בו]\u0006 \u0003בהושע בן אלה: \"ויעש הרע בעיני ה' רק לא כמלכי ישראל\u0004 אשר היו לפניו\" (מלכים ב יז, ב), \u0003וכתיב\u0004 \u0005[ונאמר]\u0006 מיד אחר כך: \u0003\"עליו עלה שלמנאסר\"\u0004 (מלכים ב יז, ג) והגלה את ישראל, ואם הושע לא עשה רע כמלכי ישראל, מדוע דווקא הוא נענש?","\u0003אמר להו\u0004 \u0005[להם]:\u0006 \u0003אותן פרדסיאות\u0004 (משמרות) \u0003שהושיב ירבעם על הדרכים כדי שלא יעלו ישראל לרגל\u0004 לירושלים \u0003בא הושע וביטלן, ואף על פי כן לא עלו ישראל לרגל,\u0004 שכבר שכחו וסרו ממנהגי אבותיהם, \u0003אמר הקדוש ברוך הוא: אותן שנים שלא עלו ישראל לרגל\u0004 — \u0003ילכו בשבי.\u0004","\u0003אמר רב חסדא אמר מר עוקבא, ואמרי לה\u0004 \u0005[ויש אומרים]\u0006 \u0003אמר רב חסדא אמר ר' ירמיה, דרש מרימר: מאי דכתיב\u0004 \u0005[מהו שנאמר]:\u0006 \u0003\"וישקד ה' על הרעה ויביאה עלינו כי צדיק ה' אלהינו\"\u0004 (דניאל ט׳:י״ד)? ויש לתמוה: וכי \u0003משום ש\"צדיק ה' אלהינו\"\u0004 בא \u0003\"וישקד ה' על הרעה ויביאה עלינו\"?\u0004","\u0003אלא\u0004 כך יש לומר: \u0003צדקה עשה הקדוש ברוך הוא עם ישראל שהגלה גלות צדקיהו ועדיין גלות יכניה קייימת\u0004 בבבל, \u0003דכתיב ביה\u0004 \u0005[שנאמר בה]\u0006 \u0003בגלות יכניה: \"החרש והמסגר אלף\"\u0004 (מלכים ב כ״ד:י״ד) שגדולי הדור הוגלו תחילה לבבל, וכיון שהם היו שם — היו לגולים בימי צדקיה מנהיגים שידריכו אותם. ומדוע מכנים כך את גדולי ישראל?","\u0003\"חרש\"\u0004 הוא רמז — \u0003שבשעה שפותחין\u0004 בדבר תורה \u0003נעשו הכל כחרשין\u0004 שאינם מבינים, \u0003\"מסגר\"\u0004 — \u0003כיון שסוגרין\u0004 ואומרים שאין הדבר מובן \u0003שוב אינן פותחין,\u0004 שאין מי שיוכל לפתור בעיות אלה. \u0003וכמה\u0004 היו? — \u0003\"אלף\".\u0004","\u0003עולא אמר:\u0004 צדקה אחרת היתה, \u0003שהקדים\u0004 (\"וישקוד\") \u0003שתי שנים\u0004 להגלותם \u0003ל\u0004ענין \u0003\"ונושנתם\"\u0004 (דברים ד, כה), שלא היו ישראל על אדמתם מנין שנים זה (שמונה מאות חמישים ושתים), אלא פחות שנתיים, כדי שלא תתקיים בהם בשלימותה הקללה האמורה באותה פרשה, של אובדן גמור."],["\u0003אמר רב אחא בר יעקב: שמע מינה\u0004 \u0005[למד מכאן],\u0006 ש\u0003\"מהרה\" דמרי עלמא\u0004 \u0005[של אדון העולם]\u0006 \u0003תמני מאה וחמשין ותרתי\u0004 \u0005[שמונה מאות וחמישים ושתיים\u0006 שנה\u0005]\u0006 \u0003הוא,\u0004 שכן נאמר בהמשך לכתוב \"ונושנתם בארץ\" — \"אבד תאבדון מהר\" (דברים ד, כו), וישראל ישבו על אדמתם במשך מנין שנים זה, ומתברר שזמן זה של \"ונושנתם\" נחשב למהר.","\u0003גט מעושה\u0004 שמכריחים בית דין (\"מעשים\") את הבעל לכותבו ולתיתו לאשתו, אם נעשה הדבר בבית דין של \u0003ישראל\u0004 — \u0003כשר, ו\u0004אם \u0003בגוים\u0004 — \u0003פסול.\u0004 אבל אם \u0003גוים\u0004 \u0003חובטין\u0004 (מכים) \u0003אותו\u0004 לבקשת בית דין ישראל \u0003ואומרים לו: \"עשה מה שישראל אומרים לך\u0004 — \u0003כ\u0004\u0003שר.\u0004","\u0003אמר רב נחמן אמר שמואל: גט המעושה בישראל,\u0004 אם עשו זאת \u0003כדין,\u0004 שחייב הוא לגרשה, כגון שאשתו אסורה עליו או שחייבוהו חכמים לגרשה, וברצונו אינו רוצה לגרשה, ומשום כך מכריחים אותו לכך — הרי זה גט \u0003כשר,\u0004 ואם \u0003שלא כדין\u0004 חייבוהו — \u0003פסול\u0004 הגט, \u0003ו\u0004מכל מקום \u0003פוסל\u0004 הוא את האשה מכהונה, לפי שאינו נחשב בטל לחלוטין.","\u0003ו\u0004אם נעשה \u0003בגוים,\u0004 אם נעשה \u0003כדין\u0004 — \u0003פסול ופוסל, שלא כדין\u0004 — \u0003אפילו ריח הגט אין בו.\u0004","על כך תוהים: \u0003מה נפשך\u0004 \u0005[מה רצונך\u0006 לומר\u0005]?\u0006 \u0003אי\u0004 \u0005[אם]\u0006 \u0003גוים בני עשויי נינהו\u0004 \u0005[עישוי,\u0006 הכרחה, \u0005הם],\u0006 כלומר, שמה שהם מכריחים לעשות יש לו תוקף, אם כן \u0003איתכשורי נמי ליתכשר\u0004 \u0005[שיהיה גם כן כשר\u0006 הגט\u0005]\u0006 אם נעשה כדין! \u0003אי לאו בני עשויי נינהו\u0004 \u0005[אם לא בני עישוי,\u0006 הכרחה, \u0005הם],\u0006 אם כן \u0003מיפסל לא ליפסל\u0004 \u0005[לא ייפסל]!\u0006","\u0003אמר רב משרשיא:\u0004 על פי \u0003דבר תורה גט מעושה בגוים כשר\u0004 הוא, \u0003ומה טעם אמרו\u0004 חכמים שהוא \u0003פסול\u0004 — כדי \u0003שלא תהא כל אחת ואחת הולכת ותולה עצמה בגוי ו\u0004על ידי פיתוי או שוחד, שיהיה הגוי כופה את בעלה לגרשה, \u0003מפקעת עצמה מיד בעלה שלא כדין.\u0004","ושואלים: \u0003אי הכי\u0004 \u0005[אם כך],\u0006 שגט מעושה על ידי גוי כשר מעיקר הדין, מדוע שנינו אם כן שאם הוא מעושה בגויים \u0003שלא כדין אפילו ריח הגט אין בו? ונהוי\u0004 \u0005[ויהיה]\u0006 הגט כמו גט מעושה \u0003שלא כדין כישראל, ומפסיל נמי לפסול\u0004 \u0005[ושיפסול גם כן]\u0006 את האשה מכהונה!","\u0003אלא, הא\u0004 \u0005[זו]\u0006 שאמר \u0003רב משרשיא\u0004 שמן התורה גט מעושה בגויים כשר \u0003בדותא\u0004 \u0005[דבר שאינו נכון]\u0006 \u0003היא,\u0004 ומעיקר הדין אף גט מעושה כדין על ידי גויים אין בו ריח הגט.","\u0003וטעמא מאי\u0004 \u0005[וטעם\u0006 הדבר \u0005מהו]?\u0006 מדוע פסולה האשה לכהונה על ידו? \u0003כדין בכדין\u0004 של \u0003ישראל\u0004 — \u0003מיחלף\u0004 \u0005[מתחלף]\u0006 אצל הבריות, שאם גט זה אין בו כלום יבואו לומר כן גם על גט מעושה כדין על ידי ישראל, ולכן אף גט זה פוסל. אבל מה שעושים גויים \u0003שלא כדין ב\u0004מה שעושים \u0003כדין\u0004 כ\u0003ישראל\u0004 — \u0003לא מיחלף\u0004 \u0005[אינו מתחלף],\u0006 ואין לחשוש שיבואו לומר כן גם על גט שנעשה כדין בישראל, ולכן אין בו כל ממש.","מסופר: \u0003אביי אשכחיה\u0004 \u0005[מצא אותו]\u0006 \u0003לרב יוסף דיתיב\u0004 \u0005[שהיה יושב\u0006 כדיין\u0005]\u0006 \u0003וקא\u0004 \u0005[והיה]\u0006 \u0003מעשה\u0004 (כופה) \u0003אגיטי\u0004 \u0005[על\u0006 מתן \u0005גיטין],\u0006 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003והא אנן\u0004 \u0005[והרי אנו]\u0006 \u0003הדיוטות אנן\u0004 \u0005[אנו],\u0006 שאין אנו דיינים סמוכים, \u0003ותניא\u0004 \u0005[ושנינו\u0006 בברייתא\u0005],\u0006 \u0003היה ר' טרפון אומר: כל מקום שאתה מוצא אגוריאות\u0004 \u0005[בתי דינים]\u0006 \u0003של גוים, אף על פי שדיניהם כדיני ישראל\u0004 — \u0003אי\u0004 (אין) \u0003אתה רשאי להיזקק להם\u0004 לדין, \u0003שנאמר:\u0004 \u0003\"ואלה המשפטים אשר תשים לפניהם\"\u0004 (שמות כא, א), ונדייק מכאן: \u0003\"לפניהם\"\u0004 — לפני דייני ישראל דווקא \u0003ולא לפני גוים. דבר אחר: \"לפניהם\"\u0004 — לפני דיינים סמוכים \u0003ולא לפני הדיוטות.\u0004 ומאחר שאנו בבבל הדיוטות שאינם סמוכים, כיצד יכולים אנו לעשות דבר שהוא דין גמור!","\u0003אמר ליה\u0004 \u0005[לו]\u0006 רב יוסף: \u0003אנן שליחותייהו קא עבדינן\u0004 \u0005[אנו את שליחותם אנו עושים],\u0006 שאנו רואים עצמנו כשליחיהם של הדיינים הסמוכים בארץ ישראל, ומכוח סמכותם אנו פועלים. \u0003מידי דהוה\u0004 \u0005[כמו שהוא\u0006 הדין\u0005]\u0006 \u0003אהודאות\u0004 \u0005[על,\u0006 אצל, \u0005הודאות]\u0006 \u0003והלואות,\u0004 שאנו דנים בהן משום שאנו נחשבים כשליחי הדיינים של ארץ ישראל.","ומקשים: \u0003אי הכי\u0004 \u0005[אם כך],\u0006 ב\u0003גזילות וחבלות נמי\u0004 \u0005[גם כן]\u0006 נהיה שליחיהם, ומדוע אמרו שבאלה אין סמכות לדיינים שבחוצה לארץ! ומשיבים: \u0003כי עבדינן שליחותייהו\u0004 \u0005[כאשר אנו עושים את שליחותם]\u0006 הרי זה \u0003במילתא דשכיחא\u0004 \u0005[בדבר המצוי],\u0006 כגון הודאות והלוואות שהן דברים רגילים שבין אדם לחבירו, ואולם \u0003במילתא דלא שכיחא\u0004 \u0005[בדבר שאינו מצוי]\u0006 כגון גזילות וחבלות — \u0003לא עבדינן שליחותייהו\u0004 \u0005[אין אנו עושים את שליחותם].\u0006","\u0003יצא שמה\u0004 (יצאה שמועה) בעיר על אשה פנויה שהיא \u0003מקודשת\u0004 — \u0003הרי זו\u0004 נחשבת \u0003מקודשת,\u0004 וכן אם יצא שמה של אשה נשואה שהיא \u0003מגורשת\u0004 — \u0003הרי זו מגורשת, ובלבד שלא יהא שם אמתלא\u0004 (הסבר, טעם) המבטלת שמועה זו.","\u0003איזו היא אמתלא?\u0004 — כגון, שהיתה שמועה בעיר ש\u0003גירש איש פלוני את אשתו,\u0004 אלא שהיה זה גט \u0003על תנאי,\u0004 ואולי לא התקיים התנאי, ואין היא מגורשת. וכן לענין קידושין, ששמעו שהיו שם קידושין אלא שהאיש \u0003זרק לה קידושיה ספק קרוב לה ספק קרוב לו\u0004 — \u0003זו היא אמתלא.\u0004","על מה שאמרנו שאם יצא שמה בעיר שמגורשת — הרי זו מגורשת, שואלים: \u0003ואסרינן לה אגברא\u0004 \u0005[ואנו אוסרים אותה על בעלה]\u0006 אם היא נשואה לכהן? \u0003והא\u0004 \u0005[והרי]\u0006 \u0003אמר רב אשי: כל קלא דבתר\u0004 \u0005[כל קול\u0006 שיוצא \u0005לאחר]\u0006 \u0003נישואין\u0004 — \u0003לא חיישינן ליה\u0004 \u0005[אין אנו חוששים לו]\u0006 ואין מוציאים אשה מבעלה בגלל שמועה בלבד!","ומשיבים: \u0003הכי קאמר\u0004 \u0005[כך אמר]:\u0006 אם \u0003יצא שמה בעיר\u0004 שהיא \u0003מקודשת\u0004 — \u0003הרי זו מקודשת\u0004 ולא תינשא לאדם אחר, בלא שתקבל קודם גט מזה שיצא עליו הקול שנשאה לאשה. אם יצא שמה שהיא \u0003מקודשת ומגורשת\u0004 ששמעו שנתקדשה לאדם מסויים ונתגרשה ממנו —"],["\u0003הרי זו\u0004 נחשבת \u0003מגורשת\u0004 ויכולה להינשא. \u0003מאי טעמא\u0004 \u0005[מהו טעם\u0006 הדבר\u0005]?\u0006 — \u0003קול ושוברו עמו\u0004 הוא, שהרי אותה שמועה שהיא מקודשת מתבטלת על ידי שמועה זו שהיא מגורשת, ופנויה היא עתה.","\u0003אמר רבא: יצא לה\u0004 על אשה פנויה \u0003שם\u0004 שהיא \u0003מזנה בעיר\u0004 — \u0003אין חוששין לה\u0004 שהיא זונה כדי לפוסלה מן הכהונה. \u0003מאי טעמא\u0004 \u0005[מה טעם\u0006 הדבר\u0005]?\u0006 — \u0003פריצותא בעלמא\u0004 \u0005[פריצות סתם,\u0006 בלבד\u0005]\u0006 \u0003הוא דחזו לה\u0004 \u0005[שראו בה],\u0006 ואין זו עדות על זנות ממש.","ומעירים: הלכה זו הריהי שנויה \u0003כ\u0004מחלוקת \u0003תנאי\u0004 \u0005[תנאים]\u0006 שאמרו: אשה ש\u0003אכלה בשוק,\u0004 או \u0003גירגרה\u0004 (הלכה נטוית גרון, בדרך שחץ) \u0003בשוק\u0004 או \u0003הניקה בשוק\u0004 — \u0003בכולן ר' מאיר אומר: תצא,\u0004 מבעלה, משום שאלה הן דרכי פריצות. \u0003ר' עקיבא אומר:\u0004 אינה יוצאת אלא \u0003משישאו ויתנו בה\u0004 (יספרו עליה אלו לאלו) שהיא מזנה \u0003מוזרות בלבנה\u0004 (נשים הטווות לאור הירח), שהדבר נעשה שמועה נפוצה, שרבים יודעים ומקבלים אותה.","\u0003אמר לו ר' יוחנן בן נורי: אם כן, לא הנחת בת לאברהם אבינו שיושבת תחת בעלה\u0004 שהרי יש הרבה נשים שמדברות דברי שקר ורכילות על חברותיהן, \u0003והתורה אמרה: \"כי מצא בה ערות דבר\u0004 וכתב לה ספר כריתות \u0003\"\u0004וכו' (דברים כד, א), \u0003ולהלן הוא אומר: \"על פי שנים עדים או על פי שלשה עדים יקום דבר\"\u0004 (דברים יט, טו), \u0003מה להלן\u0004 הכוונה \u0003דבר ברור,\u0004 בעדים, אף כאן \"ערות דבר\" צריך שיהיה \u0003דבר ברור\u0004 ואין סומכים על שמועה בלבד.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 יצאה שמועה על אשה פנויה שהיא \u0003בעולה\u0004 — \u0003אין חוששין לה\u0004 לשמועה זו ויכולה להינשא לכהן גדול. יצא קול שהיא \u0003נשואה\u0004 — \u0003אין חוששין לה.\u0004 יצא קול שהיא \u0003ארוסה\u0004 — \u0003אין חוששין לה\u0004 לשמועה זו. יצאה שמועה שנתקדשה \u0003שלא לפלוני,\u0004 שלא סיפרו מי היה החתן — \u0003אין חוששין לה\u0004 לשמועה זו. שמעו שהתארסה \u0003בעיר אחרת\u0004 — \u0003אין חוששין לה.\u0004","יצא עליה קול שהיא \u0003ממזרת\u0004 — \u0003אין חוששין לה.\u0004 שהיא \u0003שפחה\u0004 — \u0003אין חוששין לה.\u0004","וכן אם יצאה שמועה ש\u0003הקדיש פלוני\u0004 את \u0003נכסיו,\u0004 או ש\u0003הפקיר פלוני\u0004 את \u0003נכסיו\u0004 — \u0003אין חוששין להן\u0004 שיוכל ההקדש או אדם אחר להחזיק בנכסיו.","\u0003אמר עולא:\u0004 מה שאמרו במשנתנו שאם יצא שמה בעיר הריהי מקודשת, \u0003לא\u0004 מדובר \u0003ששמעו קול הברה\u0004 (קול שמועה) בלבד, \u0003אלא\u0004 שהיו גם מעשים מוכיחים \u0003כדי שיהו נרות דולקות ומטות מוצעות\u0004 בביתה של אותה אשה, כמנהג נשים המתקדשות, \u0003ובני אדם נכנסין ויוצאין ואומרים \"פלונית מתקדשת היום\".\u0004","ותוהים על הלשון: ומדוע נחשוש אם אומרים \u0003\"מתקדשת\"? ודלמא\u0004 \u0005[ושמא]\u0006 \u0003לא אקדשה\u0004 \u0005[נתקדשה]\u0006 לבסוף, שהרי אין הקול מעיד אלא שהתכוונו לקידושין! אלא \u0003אימא\u0004 \u0005[אמור]\u0006 שאומרים כך: \u0003\"פלונית נתקדשה היום\".\u0004","\u0003וכן תני\u0004 \u0005[שנה]\u0006 \u0003לוי\u0004 בברייתא: \u0003לא שישמעו קול הברה, אלא כדי שיהו נרות דולקות ומטות מוצעות, ונשים טוות לאור הנר ושמחות לה, ואומרות \"פלונית מתקדשת היום\".\u0004 ושוב תוהים על הלשון: \u0003\"מתקדשת\"? ודלמא\u0004 \u0005[ושמא]\u0006 \u0003לא אקדשה\u0004 \u0005[נתקדשה]\u0006 לבסוף! \u0003אמר רב פפא, אימא\u0004 \u0005[אמור]:\u0006 \u0003\"פלונית נתקדשה היום\".\u0004","ועוד בענין זה \u0003אמר רבה בר בר חנה אמר ר' יוחנן: לא ששמעו קול הברה, אלא כדי שיהו נרות דולקות ומטות מוצעות ובני אדם נכנסין ויוצאין,\u0004 במקרה זה אם \u0003אמרו דבר\u0004 שסיפרו במפורש ששמחה זו היתה שמחת קידושין — \u0003זה הוא קול, לא אמרו דבר,\u0004 שלא אמרו במפורש מה טעם השמחה — \u0003זהו אמתלא,\u0004 שאם יצא אחר כך קול שנתקדשה — שמא בגלל השמחה שעשו בבית זה הגיעו אנשים למסקנה זו.","ותוהים: אם \u0003לא אמרו?! והא\u0004 \u0005[והרי]\u0006 \u0003לא אמרו ולא כלום\u0004 ואין כאן קול ולא אמתלה! ומשיבים: אין הכוונה שזאת היא האמתלה, אלא \u0003לאפוקי\u0004 \u0005[להוציא,\u0006 למעט\u0005]\u0006 \u0003מ\u0004דברי \u0003רבה בר רב הונא,\u0004 ש\u0003אמר: אמתלא שאמרו\u0004 במשנה, שמועילה לבטל את הקול — \u0003אפילו מכאן ועד עשרה ימים\u0004 לאחר שיצא הקול — סומכים עליה, על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 כי רק כאשר \u0003לא אמרו\u0004 דבר ברור מתחילה, \u0003הוא דהויא\u0004 \u0005[שנחשבת]\u0006 \u0003אמתלא הא\u0004 \u0005[הרי]\u0006 אם \u0003אמרו\u0004 מתחילה בבירור שנתקדשה — \u0003לא הויא\u0004 \u0005[אין זו]\u0006 \u0003אמתלא\u0004 שיש בה כדי לבטל את הקול.","ועוד בענין קול, \u0003אמר ר' אבא אמר רב הונא אמר רב:\u0004 שמועה זו שאמרנו במשנה שחוששים לה \u0003לא\u0004 מדובר \u0003ששמעו קול הברה\u0004 (קול שמועה) בלבד, \u0003אלא\u0004 \u0003כדי שיאמרו: פלוני מהיכן שמע? מפלוני, ופלוני מפלוני, ובודקין\u0004 בית דין \u0003והולכין\u0004 ממקבל השמועה למוסרה \u0003עד שמגיעין לדבר הברור,\u0004 למקור הראשון המעיד שכך ראה.","ותוהים: אם מגיעים ל\u0003דבר הברור,\u0004 הלא \u0003עדות מעלייתא הוא\u0004 \u0005[מעולה היא]!\u0006 ואין זה עוד קול אלא עדות ממש! \u0003אלא, כי אתא\u0004 \u0005[כאשר בא]\u0006 \u0003רב שמואל בר יהודה\u0004 מארץ ישראל, \u0003אמר\u0004 בשם \u0003ר' אבא אמר רב הונא אמר רב: לא ששמעו קול הברה, אלא כדי שיאמרו פלוני מהיכן שמע? מפלוני, ופלוני מפלוני, והלכו להם\u0004 העדים הראשונים \u0003למדינת הים.\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי לרב יוסף: מבטלינן קלא\u0004 \u0005[מבטלים אנו קול]\u0006 לגמרי, \u0003או לא מבטלינן\u0004 \u0005[מבטלים אנו]?\u0006 שאם יצאה שמועה על דבר, ולא נתבררה, האם צריכים בית דין לבטל את הפצת השמועה? \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003מדאמר\u0004 \u0005[ממה שאמר]\u0006 \u0003רב חסדא\u0004 שאין סומכים על קול \u0003עד שישמעו\u0004 שמועה \u0003מפי הכשרים,\u0004 משמע שמקילים בענין זה של קול ואין סומכים עליו כל כך, ומשום כך \u0003שמע מינה\u0004 \u0005[למד מכאן]:\u0006 \u0003מבטלינן קלא\u0004 \u0005[מבטלים אנו\u0006 את \u0005הקול].\u0006","\u0003אמר ליה\u0004 \u0005[לו]\u0006 אביי: \u0003אדרבה\u0004 \u0005[להיפך],\u0006 \u0003מ\u0004מה ש\u0003אמר רב ששת: אפילו מפי נשים הוי\u0004 \u0005[הריהו]\u0006 \u0003קול,\u0004 משמע שמחמירים אנו בענין זה של קול לסמוך עליו, ולכן \u0003שמע מינה\u0004 \u0005[למד מכאן]:\u0006 \u0003לא מבטלינן קלא\u0004 \u0005[אין אנו מבטלים קול]!\u0006","\u0003אמר ליה\u0004 \u0005[לו]\u0006 רב יוסף: \u0003אתרוותא נינהו\u0004 \u0005[מקומות הם],\u0006 כלומר, הבדלי פסק אלה תלויים במנהגי מקומות שונים; \u0003בסורא מבטלי קלא\u0004 \u0005[\u0006היו \u0005מבטלים קול],\u0006 \u0003בנהרדעא לא מבטלי קלא\u0004 \u0005[\u0006היו \u0005מבטלים קול].\u0006","מסופר: \u0003ההיא דנפק עלה קלא דאיקדשה לבר בי רב\u0004 \u0005[אשה אחת שיצא עליה קול שהתקדשה לבן בית הרב,\u0006 אחד מתלמידי החכמים\u0005],\u0006 \u0003אתייה רב חמא לאבוה\u0004 \u0005[הביא רב חמא את אביה],\u0006 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003אימא לי היכי הוה עובדא\u0004 \u0005[אמור לי\u0006 בדיוק \u0005כיצד היה המעשה]?\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 האב: \u0003על תנאי קדיש\u0004 \u0005[קידש]\u0006 אותה, \u0003אדעתא\u0004 \u0005[על דעת]\u0006 ש\u0003לא אזיל\u0004 \u0005[ילך]\u0006 \u0003ל\u0004מקום הנקרא \u0003בי חוזאי, ואזל\u0004 \u0005[והלך]\u0006 וקידושיה איפוא בטלים. \u0003אמר ליה\u0004 \u0005[לו]\u0006 רב חמא: \u0003כיון דבעידנא דהואי קלא\u0004 \u0005[שבזמן שהיה קול]\u0006 \u0003לא הואי\u0004 \u0005[היתה]\u0006 \u0003אמתלא\u0004 זו, \u0003לאו כל כמינך דמחזקת\u0004 \u0005[אין זה בכוחך שתחזיק]\u0006 \u0003אמתלא\u0004 ואנחנו חוששים לקול זה.","מסופר: \u0003ההיא דנפק עלה קלא דאיקדשה באציפא דתוחלא בעינא\u0004 \u0005[אשה אחת שיצא עליה קול שנתקדשה בחותלת של תמרים במעיין],\u0006 של \u0003בי שיפי. שלחה רב אידי בר אבין לקמיה\u0004 \u0005[לפני]\u0006 \u0003אביי\u0004 שאלה זו: \u0003כי האי גוונא מאי\u0004 \u0005[כגון זה מהו],\u0006 האם יש לבטל שמועה זו? \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003אפילו למאן דאמר לא מבטלינן קלא\u0004 \u0005[ל\u0006דעת \u0005מי שאומר שאין מבטלים קול],\u0006 \u0003בהא מבטלינן קלא\u0004 \u0005[בזה אנו מבטלים\u0006 את \u0005הקול]\u0006 ואין חוששים ללעז הבריות, ומדוע? \u0003מימר אמרי\u0004 \u0005[אומרים\u0006 אנשים\u0005]:\u0006 \u0003עיינו\u0004 ובדקו \u0003בהו רבנן\u0004 \u0005[בהם חכמים]\u0006 \u0003בקידושיה ולא הוה בהו\u0004 \u0005[היה בהם]\u0006 \u0003שוה פרוטה\u0004 ולכן אפשר לבטל קול זה, שהרי לא יחשדו באשה זו שהיא מקודשת, אלא יניחו שבטלו הקידושין.","ועוד מסופר: \u0003ההיא דנפק עלה קלא דאיקדשה\u0004 \u0005[אשה אחת שיצא עליה קול שהתקדשה]\u0006"],["\u0003לחד מבני פלניא\u0004 \u0005[לאחד מבני\u0006 אדם \u0005פלוני]\u0006 שהיו לו בנים גדולים וקטנים ולא אמרו למי מהם נתקדשה, \u0003אמר רבא: אפילו למאן דאמר\u0004 \u0005[ל\u0006דעת \u0005מי שאומר]\u0006 \u0003לא מבטלינן קלא\u0004 \u0005[אין מבטלים\u0006 את ה\u0005קול],\u0006 \u0003בהא מבטלינן קלא\u0004 \u0005[בזה מבטלים\u0006 את ה\u0005קול],\u0006 שכן \u0003מימר אמרי\u0004 \u0005[אומרים\u0006 אנשים\u0005]:\u0006 \u0003עיינו בהו רבנן בקידושי\u0004 \u0005[בדקו חכמים את הקידושין]\u0006 \u0003וקידושי קטן הוו\u0004 \u0005[היו],\u0006 שהרי לא אמרו האנשים בקול השמועה למי מהבנים התקדשה, ויאמרו שלקטן נתקדשה, ואין לחשוש ללעז בדבר זה.","ועוד מסופר: \u0003ההיא דנפק עלה קלא דאיקדשה\u0004 \u0005[אשה אחת שיצא עליה קול שהתקדשה]\u0006 \u0003לקטן הנראה כגדול,\u0004 שהיה מגודל בגופו וגבוה כגדול, \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב מרדכי לרב אשי: הוה עובדא\u0004 \u0005[היה מעשה\u0006 בקטן כזה\u0005],\u0006 \u0003ואמרו\u0004 חכמים: עדיין לא הגיע \u0003לפלגות ראובן,\u0004 כלומר הקטן הזה עדין לא הגיע למה שנקרא פלגות ראובן, \u0003שנאמר: \"לפלגות ראובן גדולים חקרי לב\"\u0004 (שופטים ה, טז), כלומר אין בו דעת כגדולים, ואין בקידושיו ממש. ואין חוששים שיטעו הבריות בדבר.","שנינו במשנה שחוששים לשמועה \u0003ובלבד\u0004 \u0003שלא תהא שם אמתלא. אמר רבה בר רב הונא: אמתלא שאמרו אפילו\u0004 נאמרה \u0003מכאן ועד עשרה ימים\u0004 לאחר השמועה — מועילה לבטל את הקול. \u0003רב זביד אמר: במקום אמתלא,\u0004 כלומר, אם יש אפשרות שתהיה בדבר אמתלה — \u0003חוששין לאמתלא\u0004 אף שלא נאמרה.","\u0003איתיביה\u0004 \u0005[הקשה לו]\u0006 \u0003רב פפא לרב זביד:\u0004 הלא שנינו: \u0003ובלבד שלא תהא שם אמתלא,\u0004 ומשמע שצריך שתהיה אמתלה בפועל! \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003במקום אמתלא קאמר\u0004 \u0005[הוא אומר]\u0006 שאין הכוונה שתהא אמתלה ממש, אלא שתהא אפשרות לאמתלה.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב כהנא לרב פפא: ואת\u0004 \u0005[ואתה]\u0006 שהקשית לרב זביד \u0003לא תסברא\u0004 \u0005[תסבור]\u0006 שכן הוא, שאין צורך באמתלה מפורשת? \u0003והתנן\u0004 \u0005[והרי שנינו\u0006 במשנה\u0005]:\u0006 \u0003נתקדשה\u0004 אשה, שהיתה מוחזקת כנשואה לאדם אחד ושמעה בו שמת, \u0003ואחר כך בא בעלה\u0004 — \u0003מותרת לחזור\u0004 אליו ואין אוסרים אותה עליו כאשה שנישאה לאחר. \u0003לאו\u0004 \u0005[האם לא]\u0006 \u0003משום דאמרינן\u0004 \u0005[שאנו אומרים]\u0006 \u0003על תנאי קדיש\u0004 \u0005[קידש]\u0006 השני, שאם יתברר שבעלה חי — ייבטלו הקידושין ולא היו אלה קידושין כלל? והרי אמתלה זו לא נאמרה במפורש!","ומשיבים: \u0003שאני התם\u0004 \u0005[שונה שם]\u0006 שאין צריך לאמתלה, \u0003דאתי\u0004 \u0005[שבא]\u0006 ה\u0003בעל וקא מערער\u0004 \u0005[ומערער],\u0006 ומובן שקידושי השני היו קידושי טעות.","ומקשים: \u0003אי הכי\u0004 \u0005[אם כך],\u0006 אף אם \u0003נישאת\u0004 אותה אשה לשני \u0003נמי\u0004 \u0005[גם כן]\u0006 תשוב לבעלה הראשון! ומדוע אמרו חכמים שבמקרה כזה אסורה לחזור אליו? ומשיבים: \u0003נישאת דעבדה איסורא\u0004 \u0005[שעשתה איסור]\u0006 ונבעלה לאחר, אף שעשתה זאת בשגגה — \u0003קנסוה רבנן\u0004 \u0005[קנסו אותה חכמים]\u0006 ואינם מבטלים את קידושי השני, אבל \u0003נתקדשה\u0004 ש\u0003לא עבדה איסורא\u0004 \u0005[עשתה איסור]\u0006 — \u0003לא קנסוה רבנן\u0004 \u0005[חכמים].\u0006","\u0003אמר רב אשי: כל קלא\u0004 \u0005[קול]\u0006 ש\u0003לא איתחזק בבי דינא\u0004 \u0005[הוחזק בבית דין]\u0006 — \u0003לאו קלא\u0004 \u0005[לא קול]\u0006 \u0003הוא\u0004 ואין סומכים על שמועה בלבד אלא אם כן נתברר בבית דין שיש מקום לחשוש לשמועה זו. \u0003ואמר רב אשי: כל קלא\u0004 \u0005[קול]\u0006 שיצא על אשה \u0003דבתר\u0004 \u0005[לאחר]\u0006 \u0003נישואין,\u0004 שכבר נתקדשה לאדם אחר קודם לכן, \u0003לא חיישינן ליה\u0004 \u0005[אין אנו חוששים לו]\u0006 להוציאה מבעלה, או אף שיתן לה אותו אדם גט מספק. ומדייקים: \u0003הא\u0004 \u0005[הרי]\u0006 קול שיצא \u0003דבתר\u0004 \u0005[לאחר]\u0006 \u0003אירוסין חיישינן ליה\u0004 \u0005[חוששים אנו לו]\u0006 ותצא מן הארוס. \u0003רב חביבא אמר: אפילו\u0004 קול \u0003דבתר\u0004 \u0005[ש\u0006יצא \u0005אחר]\u0006 \u0003אירוסין נמי לא חיישינן ליה\u0004 \u0005[גם כן אין אנו חוששים לו].\u0006 ומסכמים, \u0003והלכתא\u0004 \u0005[והלכה\u0006 היא\u0005]:\u0006 \u0003לא חיישינן ליה\u0004 \u0005[אין אנו חוששים לו].\u0006","\u0003אמר רב ירמיה בר אבא, שלחו ליה\u0004 \u0005[לו]\u0006 \u0003מבי\u0004 \u0005[מבית]\u0006 \u0003רב,\u0004 קבוצת תלמידי רב, לאחר מותו, שאלה זו \u0003לשמואל: ילמדנו רבינו, יצא עליה קול מראשון\u0004 שהתקדשה לו, \u0003ובא אחר וקדשה קידושי תורה\u0004 בעדות ברורה, \u0003מהו\u0004 הדין? \u0003שלח להו\u0004 \u0005[להם]:\u0006 \u0003תצא\u0004 מן השני, \u0003והעמידו הדבר על בוריו\u0004 (בררו כיצד בדיוק היה הדבר) \u0003והודיעוני.\u0004","ושואלים: \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"והעמידו הדבר על בוריו\"? אילימא\u0004 \u0005[אם תאמר]\u0006 \u0003דאי מגליא מילתא דקידושי דקמא לאו קידושי מעליא נינהו\u0004 \u0005[שאם יתברר הדבר שקידושי הראשון לא קידושין מעולים,\u0006 כהוגן, \u0005הם]\u0006 \u0003מבטלינן קלא\u0004 \u0005[מבטלים אנו\u0006 את \u0005הקול]\u0006 ויתירוה לשני? \u0003והא\u0004 \u0005[והרי]\u0006 \u0003נהרדעא אתריה\u0004 \u0005[מקומו]\u0006 של \u0003שמואל הוא, ו\u0004אנו יודעים כי \u0003לא מבטלי קלא\u0004 \u0005[אין מבטלים קול]\u0006 בנהרדעא! \u0003אלא\u0004 כך יש להבין: \u0003דאי מיגליא מילתא דקידושי קמא קידושי מעליא נינהו\u0004 \u0005[שאם יתגלה הדבר שקידושי הראשון קידושין מעולים הם]\u0006 \u0003לא צריכה גט משני.\u0004","ומעירים: \u0003ופליגא\u0004 \u0005[חלוקה]\u0006 דעה זו של שמואל, שאינה צריכה גט מן השני על דעת \u0003רב הונא,\u0004 ש\u0003אמר רב הונא: אשת איש שפשטה ידה וקיבלה קידושין מאחר\u0004 — הרי היא \u0003מקודשת\u0004 לו מספק וצריכה גט ממנו.","ודבר זה נובע \u0003מ\u0004דברי \u0003רב המנונא,\u0004 ש\u0003אמר רב המנונא: האשה שאמרה לבעלה \"גירשתני\"\u0004 — הרי היא \u0003נאמנת,\u0004 ומדוע — \u0003חזקה אין אשה מעיזה פניה\u0004 (מתחצפת) \u0003בפני בעלה\u0004 עד כדי כך לולא אמת בפיה. ולכן, על סמך כלל זה, אם זו שיצא עליה שם ארוסה קיבלה קידושין מאדם אחר — די בכך כדי לבטל את הקול, שהרי בוודאי לא היתה מקבלת קידושין ממנו אילו היתה באמת ארוסה לאדם אחר.","ושואלים: \u0003ואידך\u0004 \u0005[והאחר],\u0006 שמואל שאינו סבור כרב הונא מה דעתו? ומשיבים: הוא סבור \u0003כי אתמר\u0004 \u0005[\u0006ש\u0005כאשר נאמרו]\u0006 דברי \u0003רב המנונא\u0004 הרי זה כשאומרת לו \u0003בפניו\u0004 שגירשה, אבל אם אומרת כן \u0003שלא בפניו\u0004 — הריהי \u0003מעיזה ומעיזה.\u0004 ואף כאן, האשה מעיזה פניה לקבל קידושין מאחר, כיון שאין זה בפני בעלה.","ושואלים: אם \u0003לא מצאו דבר על בוריו,\u0004 שלא נתברר לחלוטין שנתקדשה לראשון, מהו הדין?","\u0003אמר רב הונא: מגרש\u0004 אותה \u0003ראשון ונושא\u0004 אותה \u0003שני. אבל\u0004 שיהיה \u0003מגרש שני ונושא ראשון\u0004 — \u0003לא.\u0004 ומסבירים: \u0003מאי טעמא\u0004 \u0005[מה טעם\u0006 הדבר\u0005]\u0006 — \u0003אתי למימר\u0004 \u0005[יבואו\u0006 אנשים \u0005לומר]\u0006 ש\u0003מחזיר גרושתו מן האירוסין,\u0004 שיחשבו שאכן קידשה הראשון בשעתו, אלא נמלך וגירשה, ולכן נתקדשה לאחר ונתגרשה ממנו, והראשון מחזירה אליו, ועובר על האיסור המפורש בתורה להחזיר גרושתו אחרי שנתקדשה לאחר.","ואילו \u0003רב שיננא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב אידי אמר: אף מגרש שני ונושא ראשון,\u0004 ואין חשש שיבואו אנשים לומר שמחזיר גרושתו, שכן \u0003מימר אמרי\u0004 \u0005[אומרים\u0006 אנשים\u0005]:\u0006 \u0003עייני רבנן בקידושי\u0004 \u0005[בדקו חכמים בקידושין],\u0006 \u0003וקידושי טעות הוה\u0004 \u0005[היה].\u0006","ועוד שואלים: \u0003יצא עליה קול\u0004 (בלי עדות ברורה) \u0003מזה ומזה\u0004 שנתקדשה לשני בני אדם, בזה אחר זה, \u0003מהו? אמר רב פפא: אף זו מגרש\u0004 אותה \u0003ראשון ונושא\u0004 אותה \u0003שני,\u0004 מפני החשש שאמרנו, שיאמרו שמחזיר גרושתו שנתקדשה לאחר. ואילו \u0003אמימר אמר: מותרת לשניהם,\u0004 בין לראשון בין לשני, ואחד מהם מגרש והאחר יכול לכנוס אותה."],["\u0003והלכתא\u0004 \u0005[והלכה\u0006 היא\u0005]:\u0006 \u0003מותרת לשניהם.\u0004","\u0003בית שמאי אומרים: לא יגרש אדם את אשתו אלא אם כן מצא בה דבר ערוה\u0004 שזנתה או יש לו מקום לחשוד בה בכך, \u0003שנאמר\u0004 בגירושי אשה: \u0003\"כי מצא בה ערות דבר\"\u0004 (דברים כד, א)","\u0003ובית הלל אומרים: אפילו\u0004 מצא בה חיסרון כל שהוא כגון ש\u0003הקדיחה תבשילו\u0004 שעשתה אותו מלוח מדי, \u0003שנאמר: \"כי מצא בה ערות דבר\",\u0004 כלומר, כל דבר חסרון.","\u0003ר' עקיבא אומר: אפילו מצא\u0004 אשה \u0003אחרת נאה הימנה\u0004 ורוצה לשאתה יכול לגרש את אשתו, \u0003שנאמר: \"והיה אם לא תמצא חן בעיניו\"\u0004 (דברים כד, א).","\u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005]:\u0006 \u0003אמרו בית הלל לבית שמאי: והלא כבר נאמר \"דבר\",\u0004 משמע שמשום כל דבר חסרון יכול לגרשה! \u0003אמרו להם בית שמאי: והלא כבר נאמר \"ערות\"!\u0004","\u0003אמרו להם בית הלל: אם נאמר \"ערות\" ולא נאמר \"דבר\", הייתי אומר\u0004 — \u0003משום ערוה תצא\u0004 מבעלה, \u0003משום דבר אחר לא תצא, לכך נאמר \"דבר\". ואילו נאמר\u0004 רק \u0003\"דבר\" ולא נאמר \"ערות\", הייתי אומר\u0004 אם יצאה רק \u0003משום דבר\u0004 של חיסרון כלשהו — \u0003תנשא לאחר\u0004 וכפי שממשיך הכתוב \"ויצאה מביתו והלכה והיתה לאיש אחר\" (דברים כ״ד:ב׳, פסוק ב), \u0003ו\u0004אולם אם יצאה \u0003משום ערוה\u0004 — \u0003לא תנשא לאחר\u0004 ואסורה לכל אדם. \u0003לכך נאמר \"ערות\",\u0004 לומר שאף זו שנתגרשה משום דבר ערווה ממש מותרת להינשא.","ושואלים: \u0003ובית שמאי, האי\u0004 \u0005[\u0006הביטוי \u0005הזה]\u0006 \u0003\"דבר\" מאי עבדי ליה\u0004 \u0005[מה עושים\u0006 הם \u0005בו]?\u0006 שהרי לדעתם מדובר בערווה דווקא! ומשיבים: \u0003נאמר כאן\u0004 בקשר לערווה \u0003\"דבר\" ונאמר להלן\u0004 בענייני עדות \u0003\"דבר\",\u0004 שנאמר שם \u0003\"על פי שני עדים או על פי שלשה עדים יקום דבר\"\u0004 (דברים יט, טו), \u0003מה להלן בשני עדים, אף כאן\u0004 להביא לגירושיה של אשה משום ערווה, אין מכריעים את הדבר אלא \u0003בשני עדים.\u0004","\u0003ובית הלל\u0004 טוענים: \u0003מי כתיב\u0004 \u0005[האם נאמר]\u0006 \u0003\"ערוה בדבר\",\u0004 שמשמעו שמצא בה שעברה איסור ערווה בעדות של שנים? \u0003ובית שמאי\u0004 אומרים: \u0003מי כתיב\u0004 \u0005[האם נאמר]\u0006 \u0003\"או ערוה או דבר\"\u0004 כדבריכם?","\u0003ובית הלל\u0004 אומרים: \u0003להכי כתיב\u0004 \u0005[משום כך כתוב]\u0006 \u0003\"ערות דבר\",\u0004 ש\u0003משמע הכי\u0004 \u0005[כך]\u0006 שיש צורך בערווה לעדות של שנים, \u0003ומשמע הכי\u0004 \u0005[כך]\u0006 שיכול לגרש בין משום דבר ערווה ממש, ובין משום דבר אחר.","עוד שנינו במשנה ש\u0003ר' עקיבא אומר: אפילו מצא אחרת\u0004 נאה ממנה רשאי לגרשה. ומבררים: \u0003במאי קא מיפלגי\u0004 \u0005[במה הם חלוקים]?\u0006 — \u0003ב\u0004מה שנלמד מדברי \u0003ריש לקיש,\u0004 ש\u0003אמר ריש לקיש:\u0004 הביטוי \u0003\"כי\" משמש\u0004 במקרא \u0003בארבע לשונות\u0004 (מובנים): במובן \u0003אי\u0004 \u0005[או],\u0006 במובן \u0003דלמא\u0004 \u0005[שמא],\u0006 במובן \u0003אלא\u0004 (לא כך אלא כך), במובן \u0003דהא\u0004 \u0005[שהרי,\u0006 מפני\u0005].\u0006 ולפי זה מתפרשות השיטות במשנה.","\u0003בית שמאי סברי\u0004 \u0005[סבורים]\u0006 שמה שנאמר \u0003\"והיה אם לא תמצא חן בעיניו כי מצא בה ערות דבר\"\u0004 פירושו: \u0003דהא\u0004 \u0005[שהרי]\u0006 \u0003מצא בה ערות דבר,\u0004 שזהו הטעם מדוע לא מצאה חן בעיניו, \u0003ור' עקיבא סבר\u0004 \u0005[סבור]:\u0006 \u0003\"כי מצא בה ערות דבר\",\u0004 \"כי\" פירושו \u0003אי נמי\u0004 \u0005[או גם כן],\u0006 אם \u0003מצא בה ערות דבר.\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב פפא לרבא:\u0004 לדעת בית הלל, אם \u0003לא מצא בה לא ערוה ולא דבר,\u0004 אלא גירשה סתם, \u0003מהו,\u0004 האם גירושין אלה יש להם תוקף, או שמא כיון שלא גירשה כדין — גירושיה בטלים?","\u0003אמר ליה\u0004 \u0005[לו],\u0006 \u0003מדגלי רחמנא\u0004 \u0005[ממה שגילתה תורה]\u0006 \u0003גבי\u0004 \u0005[אצל]\u0006 \u0003אונס: \"לא יוכל (ל)שלחה כל ימיו\"\u0004 (דברים כב, כט) שהכוונה היא ש\u0003כל ימיו ב\u0004ציווי של \u0003\"עמוד והחזיר\" קאי\u0004 \u0005[עומד\u0006 הוא\u0005],\u0006 שגם אם גירשה — חייב הוא להחזירה, אנחנו מבינים: דווקא \u0003התם\u0004 \u0005[שם]\u0006 \u0003הוא דגלי רחמנא\u0004 \u0005[שגילתה תורה]\u0006 כן, \u0003אבל הכא\u0004 \u0005[כאן]\u0006 — \u0003מאי דעבד עבד\u0004 \u0005[מה שעשה עשה].\u0006","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב משרשיא לרבא: אם לבו\u0004 (בדעתו) \u0003לגרשה והיא יושבת תחתיו ומשמשתו, מהו\u0004 \u0005[מה\u0006 דינו\u0005]?\u0006 — \u0003קרי עליה\u0004 \u0005[קרא עליו],\u0006 כלומר, אמר לו פסוק המתייחס לכך: \u0003\"אל תחרש על רעך רעה והוא יושב לבטח אתך\"\u0004 (משלי ג, כט).","\u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005],\u0006 \u0003היה ר' מאיר אומר: כשם שהדעות\u0004 (התייחסויות הנפש) שונות \u0003ב\u0004ענייני \u0003מאכל, כך דעות ב\u0004יחס ל\u0003נשים.\u0004 ומשל לדבר: \u0003יש לך אדם שזבוב נופל לתוך כוסו וזורקו\u0004 את הכוס עם הזבוב, \u0003ואינו שותהו, וזו היא מדת פפוס בן יהודה\u0004 שנהג קפדנות מרובה באשתו, \u0003שהיה נועל\u0004 דלת \u0003בפני אשתו ויוצא,\u0004 שלא תראה כל אדם.","\u0003ויש לך אדם שזבוב נופל לתוך כוסו וזורקו\u0004 את הזבוב \u0003ושותהו\u0004 את היין, \u0003וזו היא מדת כל אדם, שמדברת\u0004 אשה \u0003עם אחיה וקרוביה ומניחה\u0004 בעלה לעשות כן.","\u0003ויש לך אדם שזבוב נופל לתוך תמחוי\u0004 (קערת תבשיל) \u0003מוצצו\u0004 את הזבוב, \u0003ואוכלו\u0004 את התבשיל, \u0003זו היא מדת אדם רע, שרואה את אשתו יוצאה\u0004 ברחוב \u0003וראשה פרוע\u0004 (גלוי, ללא כיסוי) \u0003וטווה בשוק\u0004 שלא בדרך צניעות,"],["\u0003ו\u0004שמלתה \u0003פרומה\u0004 (קרועה, פתוחה) \u0003משני צדדיה, ורוחצת עם בני אדם\u0004 (גברים). ותוהים: \u0003עם בני אדם סלקא דעתך\u0004 \u0005[עולה על דעתך]?\u0006 דבר כזה ודאי אף אדם פחות אינו מניח לאשתו! \u0003אלא\u0004 כוונתו שרוחצת \u0003במקום\u0004 \u0003שבני אדם רוחצין\u0004 תדיר.","","אשה \u0003זו מצוה מן התורה לגרשה, שנאמר: \"כי מצא בה ערות דבר ושלחה מביתו... והלכה והיתה לאיש אחר\"\u0004 (דברים כד, א-ב). \u0003הכתוב קראו\u0004 לשני \u0003\"אחר\",\u0004 \u0003לומר, שאין זה בן זוגו לראשון,\u0004 שהוא אחר ושונה מן הראשון במהותו. שכן, \u0003זה\u0004 הראשון \u0003הוציא רשעה\u0004 זו \u0003מ\u0004תוך \u0003ביתו וזה הכניס רשעה לתוך ביתו.\u0004","אם \u0003זכה שני\u0004 — \u0003שלחה\u0004 (גירש אותה), \u0003שנאמר: \"ושנאה האיש האחרון...\u0004 ושלחה מביתו\u0003\"\u0004 (דברים כד, ג), \u0003ואם לאו\u0004 \u0005[לא]\u0006 — \u0003קוברתו, שנאמר: \"או כי ימות האיש האחרון\"\u0004 (דברים כד, ג). \u0003כדאי\u0004 (ראוי) \u0003הוא במיתה, שזה,\u0004 הראשון, \u0003הוציא רשעה מביתו, וזה הכניס רשעה לתוך ביתו.\u0004","נאמר בתוכחת הנביא על מגרשי נשותיהם \u0003\"כי שנא שלח\u0004 אמר ה' אלקי ישראל\u0003\"\u0004 (מלאכי ב, טז). \u0003ר' יהודה אומר:\u0004 כוונת הכתוב \u0003אם שנאתה\u0004 את אשתך — \u0003שלח\u0004 (גרש) אותה, ואל תדור עם אשה השנואה עליך. \u0003ר' יוחנן אומר: שנאוי\u0004 (שנוא) הוא \u0003המשלח.\u0004","ומעירים: \u0003ולא פליגי\u0004 \u0005[נחלקו\u0006 בדבר\u0005]:\u0006 \u0003הא\u0004 \u0005[זה]\u0006 מדובר \u0003בזוג ראשון,\u0004 שלא יגרש את אשתו הראשונה אלא יסבול אותה, \u0003הא\u0004 \u0005[זה]\u0006 מדובר \u0003בזוג שני,\u0004 שאם שונא אותה ראוי לו לשלח אותה. ש\u0003אמר ר' אלעזר: כל המגרש אשתו ראשונה\u0004 — \u0003אפילו מזבח מוריד עליו דמעות, שנאמר: \"וזאת שנית תעשו כסות דמעה את מזבח ה' בכי ואנקה מאין עוד פנות אל המנחה ולקחת רצון מידכם. ואמרתם על מה על כי ה' העיד בינך ובין אשת נעוריך אשר אתה בגדתה בה והיא חברתך ואשת בריתך\"\u0004 (מלאכי ב, יג-יד) משמע שאשת נעורים (זיווג ראשון) אין לגרש, כי שנוא לפני המקום מי שמגרש את אשת נעוריו שנקשרה עמו בחברה ובברית.","",""]]};
